fn decode_provider_unit_enum<T: Copy>(
    value: &RuntimeJson,
    variants: &[RuntimeEnumVariant<'_>],
    values: &[T],
) -> Result<T, RuntimeCodecError> {
    runtime_codec::decode_external(value, variants, |variant| match variant {
        RuntimeExternalVariant::Unit { variant } => values
            .get(variant)
            .copied()
            .ok_or_else(|| RuntimeCodecError::new(RuntimeCodecErrorKind::UnknownEnumVariant)),
        RuntimeExternalVariant::Payload { .. } => Err(RuntimeCodecError::new(
            RuntimeCodecErrorKind::InvalidEnumShape,
        )),
    })
}

fn runtime_diagnostic(value: &RuntimeString) -> String {
    let mut output = String::new();
    let mut units = value.as_utf16().iter().copied().peekable();
    while let Some(unit) = units.next() {
        if (0xd800..=0xdbff).contains(&unit) {
            if let Some(low) = units
                .peek()
                .copied()
                .filter(|low| (0xdc00..=0xdfff).contains(low))
            {
                units.next();
                let point =
                    0x10000 + ((u32::from(unit) - 0xd800) << 10) + (u32::from(low) - 0xdc00);
                output.push(char::from_u32(point).expect("valid surrogate pair"));
            } else {
                use std::fmt::Write as _;
                write!(&mut output, "\\u{unit:04x}").expect("writing to String cannot fail");
            }
        } else if (0xdc00..=0xdfff).contains(&unit) {
            use std::fmt::Write as _;
            write!(&mut output, "\\u{unit:04x}").expect("writing to String cannot fail");
        } else {
            output.push(char::from_u32(u32::from(unit)).expect("non-surrogate UTF-16 unit"));
        }
    }
    output
}

fn runtime_eq_utf8(value: &RuntimeString, expected: &str) -> bool {
    value.as_utf16().iter().copied().eq(expected.encode_utf16())
}

fn runtime_ends_with(value: &RuntimeString, suffix: &RuntimeString) -> bool {
    value.as_utf16().ends_with(suffix.as_utf16())
}

fn runtime_starts_with(value: &RuntimeString, prefix: &RuntimeString) -> bool {
    value.as_utf16().starts_with(prefix.as_utf16())
}

fn runtime_option_eq_utf8(value: Option<&RuntimeString>, expected: &str) -> bool {
    value.is_some_and(|value| runtime_eq_utf8(value, expected))
}

fn runtime_option_in_utf8(value: Option<&RuntimeString>, expected: &[&str]) -> bool {
    value.is_some_and(|value| {
        expected
            .iter()
            .any(|expected| runtime_eq_utf8(value, expected))
    })
}

fn runtime_json_field_eq(value: &Json, field: &str, expected: &str) -> bool {
    runtime_option_eq_utf8(value.get(field).and_then(Json::as_str), expected)
}

fn runtime_json_pointer_eq(value: &Json, pointer: &str, expected: &str) -> bool {
    runtime_option_eq_utf8(value.pointer(pointer).and_then(Json::as_str), expected)
}

fn runtime_object_get<'a>(object: &'a RuntimeObject, key: &str) -> Option<&'a RuntimeJson> {
    object.get(RuntimeString::from_utf8(key))
}

fn runtime_positive_integer(value: &Json) -> Option<u64> {
    const MAX_SAFE_INTEGER: u64 = 9_007_199_254_740_991;
    value
        .as_u64()
        .filter(|number| (1..=MAX_SAFE_INTEGER).contains(number))
        .or_else(|| {
            let number = value.as_f64()?;
            (number.is_finite()
                && number.fract() == 0.0
                && number >= 1.0
                && number <= MAX_SAFE_INTEGER as f64)
                .then_some(number as u64)
        })
}

fn runtime_scalar(value: &RuntimeString, label: &str) -> Result<String, String> {
    value.try_to_utf8().map_err(|error| {
        format!(
            "{label} contains unpaired surrogate U+{:04X} at code-unit index {}",
            error.code_unit(),
            error.index()
        )
    })
}

fn eval_runtime_scalar(
    value: &RuntimeString,
    label: &str,
) -> Result<String, ProviderBehaviorEvalError> {
    runtime_scalar(value, label).map_err(ProviderBehaviorEvalError::Task)
}

fn eval_runtime_json_scalar(
    value: &RuntimeJson,
    label: &str,
) -> Result<serde_json::Value, ProviderBehaviorEvalError> {
    Ok(match value {
        RuntimeJson::Null => serde_json::Value::Null,
        RuntimeJson::Bool(value) => serde_json::Value::Bool(*value),
        RuntimeJson::Number(value) => serde_json::Number::from_f64(value.as_f64())
            .map(serde_json::Value::Number)
            .ok_or_else(|| {
                ProviderBehaviorEvalError::Task(format!("{label} contains a non-finite number"))
            })?,
        RuntimeJson::String(value) => serde_json::Value::String(eval_runtime_scalar(value, label)?),
        RuntimeJson::Array(values) => serde_json::Value::Array(
            values
                .iter()
                .enumerate()
                .map(|(index, value)| eval_runtime_json_scalar(value, &format!("{label}[{index}]")))
                .collect::<Result<Vec<_>, _>>()?,
        ),
        RuntimeJson::Object(values) => {
            let mut object = serde_json::Map::with_capacity(values.len());
            for (key, value) in values.entries() {
                let key = eval_runtime_scalar(&key, &format!("{label} object key"))?;
                object.insert(
                    key.clone(),
                    eval_runtime_json_scalar(value, &format!("{label}.{key}"))?,
                );
            }
            serde_json::Value::Object(object)
        }
    })
}

#[doc(hidden)]
pub trait RuntimeLookupKey {
    fn runtime_lookup_key(&self) -> RuntimeString;
    fn lookup_diagnostic(&self) -> String;
}

impl RuntimeLookupKey for str {
    fn runtime_lookup_key(&self) -> RuntimeString {
        RuntimeString::from_utf8(self)
    }

    fn lookup_diagnostic(&self) -> String {
        self.to_owned()
    }
}

impl RuntimeLookupKey for RuntimeString {
    fn runtime_lookup_key(&self) -> RuntimeString {
        self.clone()
    }

    fn lookup_diagnostic(&self) -> String {
        runtime_diagnostic(self)
    }
}

impl RuntimeLookupKey for String {
    fn runtime_lookup_key(&self) -> RuntimeString {
        RuntimeString::from_utf8(self)
    }

    fn lookup_diagnostic(&self) -> String {
        self.clone()
    }
}

fn runtime_json_pointer<'a>(
    value: &'a RuntimeJson,
    pointer: &RuntimeString,
) -> Option<&'a RuntimeJson> {
    let units = pointer.as_utf16();
    if units.is_empty() {
        return Some(value);
    }
    if units[0] != u16::from(b'/') {
        return None;
    }
    let mut current = value;
    for raw in units[1..].split(|unit| *unit == u16::from(b'/')) {
        let mut decoded = Vec::with_capacity(raw.len());
        let mut index = 0;
        while index < raw.len() {
            if raw[index] == u16::from(b'~') && index + 1 < raw.len() {
                match raw[index + 1] {
                    unit if unit == u16::from(b'0') => {
                        decoded.push(u16::from(b'~'));
                        index += 2;
                        continue;
                    }
                    unit if unit == u16::from(b'1') => {
                        decoded.push(u16::from(b'/'));
                        index += 2;
                        continue;
                    }
                    _ => {}
                }
            }
            decoded.push(raw[index]);
            index += 1;
        }
        let token = RuntimeString::from_utf16(decoded);
        current = match current {
            RuntimeJson::Object(object) => object.get(token),
            RuntimeJson::Array(array) => token
                .try_to_utf8()
                .ok()
                .and_then(|token| token.parse::<usize>().ok())
                .and_then(|index| array.get(index)),
            _ => None,
        }?;
    }
    Some(current)
}

fn runtime_trim(value: &RuntimeString) -> RuntimeString {
    fn next_scalar(units: &[u16], index: usize) -> (Option<char>, usize) {
        let unit = units[index];
        if (0xd800..=0xdbff).contains(&unit)
            && index + 1 < units.len()
            && (0xdc00..=0xdfff).contains(&units[index + 1])
        {
            let point = 0x10000
                + ((u32::from(unit) - 0xd800) << 10)
                + (u32::from(units[index + 1]) - 0xdc00);
            (char::from_u32(point), 2)
        } else if (0xd800..=0xdfff).contains(&unit) {
            (None, 1)
        } else {
            (char::from_u32(u32::from(unit)), 1)
        }
    }

    let units = value.as_utf16();
    let mut start = 0;
    while start < units.len() {
        let (scalar, width) = next_scalar(units, start);
        if !scalar.is_some_and(char::is_whitespace) {
            break;
        }
        start += width;
    }
    let mut end = units.len();
    while end > start {
        let candidate = if end >= 2
            && (0xdc00..=0xdfff).contains(&units[end - 1])
            && (0xd800..=0xdbff).contains(&units[end - 2])
        {
            end - 2
        } else {
            end - 1
        };
        let (scalar, _) = next_scalar(units, candidate);
        if !scalar.is_some_and(char::is_whitespace) {
            break;
        }
        end = candidate;
    }
    value.slice_utf16(start..end)
}

fn runtime_contains_exact(haystack: &RuntimeString, needle: &RuntimeString) -> bool {
    needle.is_empty()
        || haystack
            .as_utf16()
            .windows(needle.len_utf16())
            .any(|window| window == needle.as_utf16())
}

fn runtime_find_utf8(value: &RuntimeString, start: usize, needle: &str) -> Option<usize> {
    let needle = needle.encode_utf16().collect::<Vec<_>>();
    value
        .as_utf16()
        .get(start..)?
        .windows(needle.len())
        .position(|window| window == needle)
        .map(|offset| start + offset)
}

fn runtime_join(values: impl IntoIterator<Item = RuntimeString>, separator: &str) -> RuntimeString {
    let separator = RuntimeString::from_utf8(separator);
    let mut values = values.into_iter();
    let Some(mut joined) = values.next() else {
        return RuntimeString::default();
    };
    for value in values {
        joined = joined.concat(&separator).concat(&value);
    }
    joined
}

fn runtime_lowercase(value: &RuntimeString) -> RuntimeString {
    let mut units = Vec::new();
    for point in value.code_points() {
        if let Some(scalar) = char::from_u32(point) {
            for lowercase in scalar.to_lowercase() {
                let mut encoded = [0_u16; 2];
                units.extend_from_slice(lowercase.encode_utf16(&mut encoded));
            }
        } else {
            units.push(point as u16);
        }
    }
    RuntimeString::from_utf16(units)
}

fn runtime_ascii_lowercase(value: &RuntimeString) -> RuntimeString {
    RuntimeString::from_utf16(
        value
            .as_utf16()
            .iter()
            .copied()
            .map(|unit| {
                if (u16::from(b'A')..=u16::from(b'Z')).contains(&unit) {
                    unit + u16::from(b'a' - b'A')
                } else {
                    unit
                }
            })
            .collect::<Vec<_>>(),
    )
}

fn runtime_split_ascii(value: &RuntimeString, separator: u8) -> Vec<RuntimeString> {
    value
        .as_utf16()
        .split(|unit| *unit == u16::from(separator))
        .map(|units| RuntimeString::from_utf16(units.to_vec()))
        .collect()
}

fn runtime_strip_prefix(value: &RuntimeString, prefix: &str) -> Option<RuntimeString> {
    let prefix = prefix.encode_utf16().collect::<Vec<_>>();
    value
        .as_utf16()
        .starts_with(&prefix)
        .then(|| value.slice_utf16(prefix.len()..))
}

macro_rules! impl_runtime_object_codec {
    ($type:ty { $($field:ident => $wire:literal),+ $(,)? }) => {
        impl RuntimeEncode for $type {
            fn encode_runtime(&self, out: &mut RuntimeEncoder) -> Result<(), RuntimeCodecError> {
                let mut object = RuntimeObjectEncoder::new();
                $(object.field($wire, &self.$field)?;)+
                out.emit(RuntimeJson::Object(object.finish()))
            }
        }

        impl RuntimeDecode for $type {
            fn decode_runtime(value: &RuntimeJson) -> Result<Self, RuntimeCodecError> {
                runtime_codec::decode_object(value, true, |object| {
                    Ok(Self {
                        $($field: object.required($wire, &[])?,)+
                    })
                })
            }
        }
    };
}

macro_rules! exact_json {
    (null) => {
        RuntimeJson::Null
    };
    ({}) => {
        RuntimeJson::Object(RuntimeObject::new())
    };
    ([ $($value:tt),* $(,)? ]) => {
        RuntimeJson::Array(vec![$(exact_json!($value)),*])
    };
    ({ $($key:literal : $value:tt),* $(,)? }) => {{
        let mut object = RuntimeObject::new();
        $(object.insert($key, exact_json!($value));)*
        RuntimeJson::Object(object)
    }};
    ($value:expr) => {
        runtime_codec::encode_value(&$value).expect("exact JSON expression must encode")
    };
}

