#[derive(Debug, thiserror::Error)]
pub enum ProviderBehaviorManifestError {
    #[error("invalid provider behavior manifest JSON: {0}")]
    Codec(#[from] RuntimeCodecError),
    #[error("invalid provider behavior manifest: {0}")]
    Invalid(String),
    #[error("unknown provider behavior task: {0}")]
    UnknownTask(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct ProviderBehaviorManifest {
    pub schema_version: u32,
    pub baseline_revision: RuntimeString,
    pub tasks: Vec<TaskContract>,
    pub suites: BTreeMap<RuntimeString, Vec<RuntimeString>>,
}

