#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct TaskEngineConfig {
    pub code_mode: bool,
    pub edited_files: bool,
    pub fork: bool,
    pub deferred_threshold: Option<usize>,
}

impl RuntimeEncode for TaskEngineConfig {
    fn encode_runtime(&self, out: &mut RuntimeEncoder) -> Result<(), RuntimeCodecError> {
        let Self {
            code_mode,
            edited_files,
            fork,
            deferred_threshold,
        } = self;
        let mut object = RuntimeObjectEncoder::new();
        object.field("codeMode", code_mode)?;
        object.field("editedFiles", edited_files)?;
        object.field("fork", fork)?;
        object.field("deferredThreshold", deferred_threshold)?;
        out.emit(RuntimeJson::Object(object.finish()))
    }
}

impl RuntimeDecode for TaskEngineConfig {
    fn decode_runtime(value: &RuntimeJson) -> Result<Self, RuntimeCodecError> {
        runtime_codec::decode_object(value, true, |object| {
            Ok(Self {
                code_mode: object.required("codeMode", &[])?,
                edited_files: object.required("editedFiles", &[])?,
                fork: object.required("fork", &[])?,
                deferred_threshold: object.optional("deferredThreshold", &[])?,
            })
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum EvalPermissionMode {
    BypassPermissions,
    Default,
}

impl RuntimeEncode for EvalPermissionMode {
    fn encode_runtime(&self, out: &mut RuntimeEncoder) -> Result<(), RuntimeCodecError> {
        let tag = match self {
            Self::BypassPermissions => "bypassPermissions",
            Self::Default => "default",
        };
        runtime_codec::encode_external_unit(out, tag)
    }
}

impl RuntimeDecode for EvalPermissionMode {
    fn decode_runtime(value: &RuntimeJson) -> Result<Self, RuntimeCodecError> {
        decode_provider_unit_enum(
            value,
            &[
                RuntimeEnumVariant::new("bypassPermissions", &[]),
                RuntimeEnumVariant::new("default", &[]),
            ],
            &[Self::BypassPermissions, Self::Default],
        )
    }
}

