#[serde(rename_all = "snake_case")]
pub enum EvalProfile {
    Anthropic,
    Openai,
    Generic,
    Qwen,
}

impl RuntimeEncode for EvalProfile {
    fn encode_runtime(&self, out: &mut RuntimeEncoder) -> Result<(), RuntimeCodecError> {
        let tag = match self {
            Self::Anthropic => "anthropic",
            Self::Openai => "openai",
            Self::Generic => "generic",
            Self::Qwen => "qwen",
        };
        runtime_codec::encode_external_unit(out, tag)
    }
}

impl RuntimeDecode for EvalProfile {
    fn decode_runtime(value: &RuntimeJson) -> Result<Self, RuntimeCodecError> {
        decode_provider_unit_enum(
            value,
            &[
                RuntimeEnumVariant::new("anthropic", &[]),
                RuntimeEnumVariant::new("openai", &[]),
                RuntimeEnumVariant::new("generic", &[]),
                RuntimeEnumVariant::new("qwen", &[]),
            ],
            &[Self::Anthropic, Self::Openai, Self::Generic, Self::Qwen],
        )
    }
}

fn eval_profile_key(profile: EvalProfile) -> RuntimeString {
    RuntimeString::from(match profile {
        EvalProfile::Anthropic => "anthropic",
        EvalProfile::Openai => "openai",
        EvalProfile::Generic => "generic",
        EvalProfile::Qwen => "qwen",
    })
}

fn encode_eval_profile_map<V: RuntimeEncode>(
    values: &BTreeMap<EvalProfile, V>,
) -> Result<RuntimeJson, RuntimeCodecError> {
    let mut object = RuntimeObject::new();
    for (profile, value) in values {
        let key = eval_profile_key(*profile);
        object.insert(
            key.clone(),
            runtime_codec::encode_value(value).map_err(|error| error.prepend(key))?,
        );
    }
    Ok(RuntimeJson::Object(object))
}

fn decode_eval_profile_map<V: RuntimeDecode>(
    value: &RuntimeJson,
) -> Result<BTreeMap<EvalProfile, V>, RuntimeCodecError> {
    let RuntimeJson::Object(object) = value else {
        return Err(RuntimeCodecError::new(
            RuntimeCodecErrorKind::ExpectedObject,
        ));
    };
    object
        .entries()
        .map(|(key, value)| {
            let profile = EvalProfile::decode_runtime(&RuntimeJson::String(key.clone()))
                .map_err(|error| error.prepend(key.clone()))?;
            let value = V::decode_runtime(value).map_err(|error| error.prepend(key))?;
            Ok((profile, value))
        })
        .collect()
}

