#[derive(Debug, Clone, PartialEq)]
pub enum ScoreRule {
    FinalTextEquals {
        value: RuntimeString,
    },
    FinalTextRegex {
        pattern: RuntimeString,
    },
    /// The fixed source's negative final-text assertion. Kept separate because
    /// Rust's regex engine intentionally has no lookaround.
    FinalTextNotRegex {
        pattern: RuntimeString,
    },
    /// Parse the final text as JSON and compare one RFC 6901 pointer exactly.
    FinalJsonFieldEquals {
        pointer: RuntimeString,
        value: RuntimeJson,
    },
    FileRegex {
        path: RuntimeString,
        pattern: RuntimeString,
    },
    JsonFile {
        path: RuntimeString,
        equals: BTreeMap<RuntimeString, RuntimeJson>,
    },
    CommandSuccess {
        program: RuntimeString,
        args: Vec<RuntimeString>,
    },
}

