impl ProviderBehaviorManifest {
    pub fn task_names(&self) -> Vec<RuntimeString> {
        self.tasks.iter().map(|task| task.name.clone()).collect()
    }

    pub fn suite(&self, name: &str) -> Option<&[RuntimeString]> {
        self.suites
            .get(&RuntimeString::from(name))
            .map(Vec::as_slice)
    }

    pub fn task<T: RuntimeLookupKey + ?Sized>(
        &self,
        name: &T,
    ) -> Result<&TaskContract, ProviderBehaviorManifestError> {
        let key = name.runtime_lookup_key();
        self.tasks
            .iter()
            .find(|task| task.name == key)
            .ok_or_else(|| ProviderBehaviorManifestError::UnknownTask(name.lookup_diagnostic()))
    }

    pub fn unique_task_profile_keys(
        &self,
    ) -> Result<BTreeSet<(RuntimeString, EvalProfile)>, ProviderBehaviorManifestError> {
        let mut keys = BTreeSet::new();
        for task in &self.tasks {
            for profile in task.profiles.keys() {
                if !keys.insert((task.name.clone(), *profile)) {
                    return Err(invalid(format!(
                        "duplicate task/profile key: {:?} / {:?}",
                        task.name, profile,
                    )));
                }
            }
        }
        Ok(keys)
    }

    pub fn validate(&self) -> Result<(), ProviderBehaviorManifestError> {
        if self.schema_version != 1 {
            return Err(invalid(format!(
                "schemaVersion must be 1, got {}",
                self.schema_version
            )));
        }
        if self.baseline_revision != FIXED_BASELINE_REVISION {
            return Err(invalid(format!(
                "baselineRevision must be {FIXED_BASELINE_REVISION}, got {:?}",
                self.baseline_revision,
            )));
        }

        let names = self
            .tasks
            .iter()
            .map(|task| task.name.clone())
            .collect::<Vec<_>>();
        let expected_names = EXPECTED_TASKS.map(RuntimeString::from_utf8);
        if names != expected_names {
            return Err(invalid(format!(
                "task registry must match the fixed 35-task order, got {names:?}"
            )));
        }
        let unique_names = names.iter().cloned().collect::<BTreeSet<_>>();
        if unique_names.len() != EXPECTED_TASKS.len() {
            return Err(invalid("task registry contains duplicate names"));
        }

        let suite_names = self.suites.keys().cloned().collect::<BTreeSet<_>>();
        let expected_suite_names = [
            "provider-smoke",
            "provider-core",
            "provider-qwen-boundary",
            "provider-full",
        ]
        .into_iter()
        .map(RuntimeString::from_utf8)
        .collect::<BTreeSet<_>>();
        if suite_names != expected_suite_names {
            return Err(invalid(format!(
                "suite keys must be the fixed four suites, got {suite_names:?}"
            )));
        }
        validate_suite(self, "provider-smoke", &PROVIDER_SMOKE)?;
        validate_suite(self, "provider-core", &PROVIDER_CORE)?;
        validate_suite(self, "provider-qwen-boundary", &["qwen-generic-boundary"])?;
        let expected_full = EXPECTED_TASKS
            .iter()
            .copied()
            .filter(|name| *name != "qwen-generic-boundary")
            .collect::<Vec<_>>();
        validate_suite(self, "provider-full", &expected_full)?;

        for task in &self.tasks {
            validate_task(task)?;
        }
        let keys = self.unique_task_profile_keys()?;
        if keys.len() != 100 {
            return Err(invalid(format!(
                "manifest must contain exactly 100 task/profile keys, got {}",
                keys.len()
            )));
        }
        Ok(())
    }
}

pub fn load_checked_in_manifest() -> Result<ProviderBehaviorManifest, ProviderBehaviorManifestError>
{
    let raw = include_str!("../../tests/fixtures/provider_behavior/v1/manifest.json");
    if sha256_hex(raw.as_bytes())
        != "17dce57f0210d2ed9bbe4ef4fbfb9803bfae584af813083ea2c531c702b0c825"
    {
        return Err(invalid("checked-in task manifest predecessor changed"));
    }
    let source = RuntimeString::from_utf8(raw);
    let mut manifest: ProviderBehaviorManifest = runtime_codec::decode_text(&source)?;
    manifest.validate()?;
    // Refresh the one ordinary-root fixture while retaining its signed source bytes.
    let mut matches = manifest
        .tasks
        .iter_mut()
        .filter(|task| task.name == "qwen-generic-boundary");
    let task = matches
        .next()
        .ok_or_else(|| invalid("missing generic-provider fixture"))?;
    if matches.next().is_some()
        || task.required_profiles != [EvalProfile::Qwen]
        || task.config.code_mode
        || task.config.fork
        || task.config.edited_files
        || task.config.deferred_threshold.is_some()
    {
        return Err(invalid("generic-provider fixture root contract changed"));
    }
    let expected = task
        .behavior
        .provider
        .get_mut(&RuntimeString::from_utf8("qwen"))
        .ok_or_else(|| invalid("missing generic-provider expectation"))?;
    if expected.request_tool_includes != [RuntimeString::from_utf8("task")]
        || expected.request_tool_excludes
            != ["Task", "spawn_agent", "update_plan"].map(RuntimeString::from_utf8)
    {
        return Err(invalid(
            "generic-provider tool expectation predecessor changed",
        ));
    }
    expected
        .request_tool_includes
        .push(RuntimeString::from_utf8("update_plan"));
    expected.request_tool_excludes.truncate(2);
    manifest.validate()?;
    Ok(manifest)
}

