struct LivePreludeRegistry {
    profiles: BTreeMap<(RuntimeString, EvalProfile), LivePreludeProfile>,
}

impl LivePreludeRegistry {
    fn profile<T: RuntimeLookupKey + ?Sized>(
        &self,
        task: &T,
        profile: EvalProfile,
    ) -> Result<&LivePreludeProfile, ProviderBehaviorEvalError> {
        self.profiles
            .get(&(task.runtime_lookup_key(), profile))
            .ok_or_else(|| {
                ProviderBehaviorEvalError::Adaptation(format!(
                    "live prelude registry has no exact {} / {profile:?} declaration",
                    task.lookup_diagnostic(),
                ))
            })
    }
}

fn load_live_prelude_registry(
    manifest: &ProviderBehaviorManifest,
) -> Result<LivePreludeRegistry, ProviderBehaviorEvalError> {
    let fixture = parse_live_prelude_boundaries(LIVE_PRELUDE_BOUNDARIES_BYTES)?;
    if fixture.schema_version != 1
        || fixture.baseline_revision != FIXED_BASELINE_REVISION
        || fixture.baseline_revision != manifest.baseline_revision
        || fixture.baseline_tree != FIXED_BASELINE_TREE
        || fixture.source_contract_sha256 != SOURCE_CONTRACT_SHA256
    {
        return Err(ProviderBehaviorEvalError::Adaptation(format!(
            "live prelude provenance mismatch: schema={}, fixtureRevision={:?}, manifestRevision={:?}, tree={:?}, sourceContract={:?}",
            fixture.schema_version,
            fixture.baseline_revision,
            manifest.baseline_revision,
            fixture.baseline_tree,
            fixture.source_contract_sha256
        )));
    }
    let core_names = manifest
        .suite("provider-core")
        .ok_or_else(|| ProviderBehaviorEvalError::UnknownSuite("provider-core".to_owned()))?;
    let exact_core_names = PROVIDER_CORE
        .iter()
        .map(|name| RuntimeString::from_utf8(name))
        .collect::<Vec<_>>();
    if core_names != exact_core_names || fixture.tasks.len() != exact_core_names.len() {
        return Err(ProviderBehaviorEvalError::Adaptation(format!(
            "live prelude task matrix must exactly follow provider-core: manifest={core_names:?}, fixtureCount={}",
            fixture.tasks.len()
        )));
    }
    let expected_profiles = BTreeSet::from([EvalProfile::Anthropic, EvalProfile::Openai]);
    let mut profiles = BTreeMap::new();
    for (expected_name, declaration) in exact_core_names.iter().zip(fixture.tasks) {
        if declaration.source_task != *expected_name {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude task order mismatch: expected {expected_name:?}, got {:?}",
                declaration.source_task,
            )));
        }
        let task = manifest.task(expected_name)?;
        let actual_task_hash = task_contract_sha256(task)?;
        if declaration.source_task_sha256 != actual_task_hash {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude task hash mismatch for {expected_name:?}: declared={:?}, actual={actual_task_hash}",
                declaration.source_task_sha256,
            )));
        }
        let actual_profiles = declaration
            .profiles
            .keys()
            .copied()
            .collect::<BTreeSet<_>>();
        if actual_profiles != expected_profiles {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude profiles for {expected_name:?} must be {expected_profiles:?}, got {actual_profiles:?}"
            )));
        }
        for (profile, declaration) in declaration.profiles {
            let expected_family = live_profile_family(profile)?;
            if declaration.family != expected_family {
                return Err(ProviderBehaviorEvalError::Adaptation(format!(
                    "live prelude family for {expected_name:?} / {profile:?} must be {expected_family}, got {:?}",
                    declaration.family,
                )));
            }
            validate_live_prelude_turns(expected_name, profile, &declaration.turns)?;
            let key = (expected_name.clone(), profile);
            if profiles.insert(key.clone(), declaration).is_some() {
                return Err(ProviderBehaviorEvalError::Adaptation(format!(
                    "duplicate live prelude declaration for {key:?}"
                )));
            }
        }
    }
    let expected_count = exact_core_names.len() * expected_profiles.len();
    if profiles.len() != expected_count {
        return Err(ProviderBehaviorEvalError::Adaptation(format!(
            "live prelude matrix has {} rows, expected {expected_count}",
            profiles.len()
        )));
    }
    Ok(LivePreludeRegistry { profiles })
}

fn parse_live_prelude_boundaries(
    bytes: &[u8],
) -> Result<LivePreludeBoundaries, ProviderBehaviorEvalError> {
    let actual = sha256_hex(bytes);
    if actual != LIVE_PRELUDE_BOUNDARIES_SHA256 {
        return Err(ProviderBehaviorEvalError::Adaptation(format!(
            "live prelude whole-fixture hash mismatch: expected {LIVE_PRELUDE_BOUNDARIES_SHA256}, got {actual}"
        )));
    }
    let source = std::str::from_utf8(bytes).map_err(|error| {
        ProviderBehaviorEvalError::Adaptation(format!(
            "live prelude fixture is not UTF-8 JSON source: {error}"
        ))
    })?;
    Ok(runtime_codec::decode_text(&RuntimeString::from_utf8(
        source,
    ))?)
}

fn live_profile_family(profile: EvalProfile) -> Result<&'static str, ProviderBehaviorEvalError> {
    match profile {
        EvalProfile::Anthropic => Ok("claude"),
        EvalProfile::Openai => Ok("gpt"),
        other => Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
            "live Eval supports only Anthropic or OpenAI, got {other:?}"
        ))),
    }
}

fn validate_live_prelude_turns(
    task: &RuntimeString,
    profile: EvalProfile,
    turns: &[Vec<ModelStreamEvent>],
) -> Result<(), ProviderBehaviorEvalError> {
    fn collect_token_pointers(value: &Json, pointer: &str, pointers: &mut Vec<String>) {
        match value {
            Json::String(text) if text.contains(LIVE_MODEL_TOKEN) => {
                pointers.push(pointer.to_owned());
            }
            Json::Array(values) => {
                for (index, value) in values.iter().enumerate() {
                    collect_token_pointers(value, &format!("{pointer}/{index}"), pointers);
                }
            }
            Json::Object(object) => {
                for (key, value) in object {
                    collect_token_pointers(
                        value,
                        &format!("{pointer}/{}", json_pointer_token(&key)),
                        pointers,
                    );
                }
            }
            _ => {}
        }
    }

    for (turn_index, turn) in turns.iter().enumerate() {
        if turn.is_empty() {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude {task:?} / {profile:?} turn {turn_index} is empty"
            )));
        }
        let message_starts = turn
            .iter()
            .enumerate()
            .filter_map(|(event_index, event)| match event {
                ModelStreamEvent::MessageStart { model } => Some((event_index, model)),
                _ => None,
            })
            .collect::<Vec<_>>();
        if message_starts.len() != 1
            || message_starts[0].0 != 0
            || message_starts[0].1 != LIVE_MODEL_TOKEN
        {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude {task:?} / {profile:?} turn {turn_index} must begin with exactly one message_start.model={LIVE_MODEL_TOKEN:?}"
            )));
        }
        let message_stops = turn
            .iter()
            .enumerate()
            .filter(|(_, event)| matches!(event, ModelStreamEvent::MessageStop { .. }))
            .map(|(event_index, _)| event_index)
            .collect::<Vec<_>>();
        if message_stops != [turn.len() - 1] {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude {task:?} / {profile:?} turn {turn_index} must end with exactly one message_stop"
            )));
        }
        let value = runtime_codec::encode_value(turn)?;
        let mut token_pointers = Vec::new();
        collect_token_pointers(&value, "", &mut token_pointers);
        if token_pointers != ["/0/model"] {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude {task:?} / {profile:?} turn {turn_index} has model token outside message_start.model: {token_pointers:?}"
            )));
        }
    }
    Ok(())
}

