const RETIRED_PLAN_TOOL_NAMES: &[&str] = &[
    "enter_plan_mode",
    "exit_plan_mode",
    "create_plan",
    "suggest_execution_mode",
];
const RETIRED_INITIAL_EXECUTION_MODE_SHA256: &str =
    "201afceb0e9bd721c44e8090eb00829b89b553c8e6a5f1cc4d028037f7476dc3";
const RETIRED_FINAL_EXECUTION_MODE_SHA256: &str =
    "20f718767fb05b74ceebe6c17a632dab262d9ebd19606a17fe2d748c0629a488";

fn is_retired_plan_tool_name(name: &RuntimeString) -> bool {
    RETIRED_PLAN_TOOL_NAMES
        .iter()
        .any(|retired| name == *retired)
}

/// Retire known historical tools only after the complete source catalog checks.
/// Validate every retired descriptor before mutating, and reject live resurrection.
fn migrate_baseline_retired_plan_tool_specs(
    request: &mut RuntimeJson,
    canonical_specs: &[ToolSpec],
    context: &str,
) -> Result<(), String> {
    if canonical_specs
        .iter()
        .any(|tool| is_retired_plan_tool_name(&tool.name))
    {
        return Err(format!(
            "{context} runtime catalog exposes a retired plan tool"
        ));
    }
    let tools = request
        .get_mut("tools")
        .and_then(RuntimeJson::as_array_mut)
        .ok_or_else(|| format!("{context} tools must be an array"))?;
    let mut seen = BTreeSet::new();
    for source in tools.iter() {
        let Some(name) = source.get("name").and_then(RuntimeJson::as_str) else {
            continue;
        };
        if !is_retired_plan_tool_name(name) {
            continue;
        }
        if !seen.insert(name.clone()) {
            return Err(format!("{context} repeats retired plan tool {name:?}"));
        }
        let known = if name == "enter_plan_mode" {
            source.semantic_eq_unordered(&exact_pre_create_plan_enter_plan_mode_raw_spec())
                || source.semantic_eq_unordered(&exact_final_enter_plan_mode_raw_spec())
        } else if name == "exit_plan_mode" {
            source.semantic_eq_unordered(&exact_optional_plan_exit_plan_mode_raw_spec())
                || source.semantic_eq_unordered(&exact_pre_plan_file_exit_plan_mode_raw_spec())
        } else if name == "suggest_execution_mode" {
            matches!(
                exact_runtime_json_sha256(source).as_str(),
                RETIRED_INITIAL_EXECUTION_MODE_SHA256 | RETIRED_FINAL_EXECUTION_MODE_SHA256
            )
        } else {
            // The signed source catalogs never exposed the later document tool.
            false
        };
        if !known {
            return Err(format!(
                "{context} retired plan tool {name:?} predecessor raw contract drifted: {}",
                runtime_diagnostic(&runtime_json::stringify(source))
            ));
        }
    }
    tools.retain(|tool| {
        !tool
            .get("name")
            .and_then(RuntimeJson::as_str)
            .is_some_and(is_retired_plan_tool_name)
    });
    Ok(())
}

