const PRE_ULTRA_WORKFLOW_SHA256: &str =
    "2058ed6a56cf61339c69e6d2d794870ed5d472db04b6e15c34bd756c13e94879";
const ULTRA_WORKFLOW_SHA256: &str =
    "cfddee3cf2a1ba7a5ad1d9bf2b6084dab6be57c00a20e1d5d96e5d40944f4f20";
const ORDINARY_ORCHESTRATION_SHA256: &str =
    "8137792afc7382105b795b4e6046f0ff990efe4ff995cacc3bae492b5229d465";

/// Preserve the signed source bytes and migrate only the approved opt-in clause.
/// Whole-catalog migrations must inspect the predecessor before this runs.
fn migrate_baseline_workflow_raw_spec(
    request: &mut RuntimeJson,
    canonical_specs: &[ToolSpec],
    context: &str,
) -> Result<(), String> {
    let tools = request
        .get_mut("tools")
        .and_then(RuntimeJson::as_array_mut)
        .ok_or_else(|| format!("{context} tools must be an array"))?;
    let sources: Vec<_> = tools
        .iter()
        .enumerate()
        .filter_map(|(index, tool)| {
            runtime_json_field_eq(tool, "name", "workflow").then_some(index)
        })
        .collect();
    let targets: Vec<_> = canonical_specs
        .iter()
        .filter(|spec| spec.name == "workflow")
        .collect();
    if sources.is_empty() && targets.is_empty() {
        return Ok(());
    }
    if sources.len() != 1 || targets.len() != 1 {
        return Err(format!(
            "{context} workflow source/target cardinality drifted"
        ));
    }
    let target = runtime_codec::encode_value(targets[0])
        .map_err(|error| format!("cannot encode {context} workflow target: {error}"))?;
    if exact_runtime_json_sha256(&target) != ULTRA_WORKFLOW_SHA256 {
        return Err(format!("{context} workflow target raw contract drifted"));
    }
    let source = &tools[sources[0]];
    let source_sha = exact_runtime_json_sha256(source);
    if source_sha == ULTRA_WORKFLOW_SHA256 {
        return Ok(());
    }
    if source_sha != PRE_ULTRA_WORKFLOW_SHA256 {
        return Err(format!(
            "{context} workflow predecessor raw contract drifted"
        ));
    }
    let mut migrated = source.clone();
    *migrated
        .get_mut("description")
        .expect("hash-pinned workflow description") = target
        .get("description")
        .expect("hash-pinned target description")
        .clone();
    if exact_runtime_json_sha256(&migrated) != ULTRA_WORKFLOW_SHA256 {
        return Err(format!(
            "{context} workflow migration changed unrelated raw fields"
        ));
    }
    tools[sources[0]] = migrated;
    Ok(())
}

