#[cfg(test)]
fn pinned_collaboration_parts() -> Result<Vec<SystemPromptPart>, String> {
    pinned_collaboration_parts_for_role("main")
}

fn pinned_collaboration_parts_for_role(role: &str) -> Result<Vec<SystemPromptPart>, String> {
    let fixture = runtime_json::parse(&RuntimeString::from(include_str!(
        "../../tests/fixtures/collaboration-policy-vectors.json"
    )))
    .map_err(|error| format!("cannot parse collaboration policy vectors: {error}"))?;
    let mut parts = checked_collaboration_parts(&fixture)?;
    match role {
        "main" => {}
        "child" => {
            parts[0] = runtime_codec::decode_value(&fixture["child_role"])
                .map_err(|error| format!("invalid collaboration child role: {error}"))?;
        }
        _ => return Err("unknown collaboration request role".to_owned()),
    }
    Ok(parts)
}

fn checked_collaboration_parts(fixture: &RuntimeJson) -> Result<Vec<SystemPromptPart>, String> {
    if exact_runtime_json_sha256(fixture)
        != "1c7e31e3298c1ff00b037d1ab93251118ba78b57405f620a3dded947b289129c"
    {
        return Err("collaboration policy vectors changed without approval".to_owned());
    }
    ["root_role", "explicit_mode"]
        .into_iter()
        .map(|key| {
            let value = fixture
                .get(key)
                .ok_or_else(|| format!("collaboration policy vectors omit {key}"))?;
            runtime_codec::decode_value(value)
                .map_err(|error| format!("invalid collaboration policy {key}: {error}"))
        })
        .collect()
}

/// Migrate the hash-checked predecessor and preserve the request's actual role.
/// The mode remains visible even when no spawning tool is declared.
fn migrate_baseline_collaboration_policy(
    request: &mut ModelRequest,
    _profile: &ProviderBehaviorProfile,
    role: &str,
    context: &str,
) -> Result<(), String> {
    let positions: Vec<_> = request
        .system
        .iter()
        .enumerate()
        .filter_map(|(index, part)| (part.name == "orchestration-mode").then_some(index))
        .collect();
    if request.effort.is_some()
        || positions.len() != 1
        || request
            .system
            .iter()
            .any(|part| part.name == "multi-agent-role")
    {
        return Err(format!(
            "{context} has an invalid predecessor collaboration policy"
        ));
    }
    let source = runtime_codec::encode_value(&request.system[positions[0]])
        .map_err(|error| format!("{context} cannot encode predecessor policy: {error}"))?;
    if exact_runtime_json_sha256(&source) != ORDINARY_ORCHESTRATION_SHA256 {
        return Err(format!(
            "{context} predecessor collaboration policy drifted"
        ));
    }
    let parts = pinned_collaboration_parts_for_role(role)?;
    request.system.splice(positions[0]..=positions[0], parts);
    Ok(())
}

/// Add a pinned policy to derived historical requests, retaining the complete
/// live policy in metadata comparisons so missing or altered guidance still fails.
fn migrate_baseline_ordinary_orchestration(
    request: &mut RuntimeJson,
    target: &RuntimeJson,
    context: &str,
) -> Result<(), String> {
    if exact_runtime_json_sha256(target) != ORDINARY_ORCHESTRATION_SHA256 {
        return Err(format!(
            "{context} ordinary orchestration target raw contract drifted"
        ));
    }
    if request
        .get("effort")
        .is_some_and(|value| !matches!(value, RuntimeJson::Null))
    {
        return Err(format!(
            "{context} ordinary signed predecessor effort must be null"
        ));
    }
    let system = request
        .get_mut("system")
        .and_then(RuntimeJson::as_array_mut)
        .ok_or_else(|| format!("{context} system must be an array"))?;
    let matching: Vec<_> = system
        .iter()
        .enumerate()
        .filter_map(|(index, part)| {
            runtime_json_field_eq(part, "name", "orchestration-mode").then_some(index)
        })
        .collect();
    if matching.len() > 1 {
        return Err(format!("{context} repeats orchestration-mode"));
    }
    // Signed requests already contain provider rendering. Insert before that
    // suffix to match the live assembly order without changing any other part.
    let index = system
        .iter()
        .filter(|part| !runtime_json_field_eq(part, "name", "orchestration-mode"))
        .position(|part| {
            runtime_json_field_eq(part, "name", "provider-behavior:anthropic-reminder")
                || runtime_json_field_eq(part, "name", "provider-behavior:openai-developer")
                || runtime_json_field_eq(part, "name", "total-tokens")
        })
        .unwrap_or(system.len() - matching.len());
    if let Some(&existing) = matching.first() {
        if existing != index
            || exact_runtime_json_sha256(&system[existing]) != ORDINARY_ORCHESTRATION_SHA256
        {
            return Err(format!(
                "{context} ordinary orchestration source raw contract drifted"
            ));
        }
        return Ok(());
    }
    system.insert(index, target.clone());
    Ok(())
}

fn exact_runtime_json_sha256(value: &RuntimeJson) -> String {
    sha256_hex(&runtime_json::stringify(value).to_node_utf8())
}

