fn migrate_baseline_agent_memory(
    request: &mut RuntimeJson,
    target: &RuntimeJson,
    context: &str,
) -> Result<(), String> {
    if target != &*CURRENT_AGENT_MEMORY_PART
        || exact_runtime_json_sha256(target) != CURRENT_AGENT_MEMORY_PART_SHA256
    {
        return Err(format!(
            "{context} agent-memory target raw contract drifted"
        ));
    }
    let system = request
        .get_mut("system")
        .and_then(RuntimeJson::as_array_mut)
        .ok_or_else(|| format!("{context} system must be an array"))?;
    let matching: Vec<_> = system
        .iter()
        .enumerate()
        .filter_map(|(index, part)| runtime_json_field_eq(part, "name", "memory").then_some(index))
        .collect();
    if matching.len() > 1 {
        return Err(format!("{context} repeats agent-memory parts"));
    }
    let Some(&index) = matching.first() else {
        return Ok(());
    };
    if &system[index] == target {
        return Ok(());
    }
    if system[index] != *PREVIOUS_AGENT_MEMORY_PART
        || exact_runtime_json_sha256(&system[index]) != PREVIOUS_AGENT_MEMORY_PART_SHA256
    {
        return Err(format!(
            "{context} agent-memory source raw contract drifted"
        ));
    }
    system[index] = target.clone();
    Ok(())
}

fn pinned_prompt_prefix(source: bool) -> Result<RuntimeJson, String> {
    let (text, digest) = if source {
        (
            include_str!("../../tests/fixtures/prompt_policy/previous-prefix.json"),
            "f7ff2611dbe55b7d22716b4cd57de180dc627b22794197e3e0304afd19a6b609",
        )
    } else {
        (
            include_str!("../../tests/fixtures/prompt_policy/shared-prefix.json"),
            "dbc94fa06bb9623dff3e2f856b63f0e98c76b18060d3b2527265dcf505178510",
        )
    };
    let value = runtime_json::parse(&RuntimeString::from(text))
        .map_err(|error| format!("invalid pinned prompt prefix: {error}"))?;
    if exact_runtime_json_sha256(&value) != digest {
        return Err("pinned prompt prefix digest drifted".into());
    }
    Ok(value)
}

/// Replace only the complete known stable policy prefix. Session facts and
/// every later fragment remain byte-pinned by their original contracts.
fn migrate_baseline_shared_prompt_prefix(request: &mut RuntimeJson) -> Result<(), String> {
    use crate::context::system_prompt::{build_system_prompt, SystemPromptInput};
    let source = pinned_prompt_prefix(true)?;
    let target = pinned_prompt_prefix(false)?;
    let live = build_system_prompt(&SystemPromptInput {
        config: crate::schemas::config::default_config(),
        ..Default::default()
    })
    .into_iter()
    .take_while(|part| part.cache_scope == Some(crate::types::provider::CacheScope::Global))
    .map(|part| runtime_codec::encode_value(&part).map_err(|error| error.to_string()))
    .collect::<Result<Vec<_>, _>>()?;
    if RuntimeJson::Array(live) != target {
        return Err("runtime shared prompt prefix differs from its pinned contract".into());
    }
    let source = source.as_array().ok_or("source prefix must be an array")?;
    let target = target.as_array().ok_or("target prefix must be an array")?;
    let system = request
        .get_mut("system")
        .and_then(RuntimeJson::as_array_mut)
        .ok_or("request system must be an array")?;
    if system.len() < source.len() || &system[..source.len()] != source.as_slice() {
        return Err("historical shared prompt prefix drifted".into());
    }
    if system[source.len()..].iter().any(|part| {
        source
            .iter()
            .chain(target)
            .any(|known| part.get("name") == known.get("name"))
    }) {
        return Err("request repeats a stable prompt fragment".into());
    }
    let mut suffix = system[source.len()..].to_vec();
    for part in &mut suffix {
        if !runtime_json_field_eq(part, "name", "edited-files") {
            continue;
        }
        let text = part
            .get("text")
            .and_then(RuntimeJson::as_str)
            .ok_or("edited-files text must be a string")?;
        const PREVIOUS: &str = "These files changed on disk since you last read them (edited by the user or a tool such as a formatter/linter). The shown content is current and the change was intentional — take it into account and do not revert it unless the user asks, and do not mention this notice to the user. Modified regions, by current line number:";
        const CURRENT: &str = "These files changed on disk since you last read them. The shown content is current. Preserve changes unrelated to your task and do not revert edits you did not make unless the user asks. Inspect unexpected changes before deciding how to proceed. Mention a change when it affects the requested work or requires a decision. Modified regions, by current line number:";
        let wrapper = [
            "",
            "# Diff Output\n\n",
            "<diff_output tool=\"edited_text_file_diff\">\n",
        ]
        .into_iter()
        .find(|wrapper| text.starts_with(&format!("{wrapper}{PREVIOUS}")))
        .ok_or("historical edited-files preamble drifted")?;
        let end = wrapper.encode_utf16().count() + PREVIOUS.encode_utf16().count();
        let migrated = RuntimeString::from(wrapper)
            .concat(&RuntimeString::from(CURRENT))
            .concat(&text.slice_utf16(end..));
        *part.get_mut("text").expect("validated text field") = RuntimeJson::String(migrated);
    }
    let replacement = target.iter().cloned().chain(suffix);
    system.splice(.., replacement);
    Ok(())
}

fn exact_tool_name_catalog_sha256(tools: &[RuntimeJson], context: &str) -> Result<String, String> {
    let names = tools
        .iter()
        .enumerate()
        .map(|(index, tool)| {
            tool.get("name")
                .and_then(RuntimeJson::as_str)
                .cloned()
                .map(RuntimeJson::String)
                .ok_or_else(|| format!("{context} tools[{index}].name must be a string"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(exact_runtime_json_sha256(&RuntimeJson::Array(names)))
}

