impl RuntimeEncode for TraceBehaviorProfile {
    fn encode_runtime(&self, out: &mut RuntimeEncoder) -> Result<(), RuntimeCodecError> {
        let mut object = RuntimeObjectEncoder::new();
        object.field("provider", &self.provider)?;
        if let Some(family) = &self.family {
            object.field("family", family)?;
        }
        object.field("promptStyle", &self.prompt_style)?;
        object.field("toolDescriptionStyle", &self.tool_description_style)?;
        object.field(
            "prefersExplicitParallelismHint",
            &self.prefers_explicit_parallelism_hint,
        )?;
        object.field(
            "prefersExplicitDelegationCriteria",
            &self.prefers_explicit_delegation_criteria,
        )?;
        object.field("reasoningContinuity", &self.reasoning_continuity)?;
        out.emit(RuntimeJson::Object(object.finish()))
    }
}

impl RuntimeDecode for TraceBehaviorProfile {
    fn decode_runtime(value: &RuntimeJson) -> Result<Self, RuntimeCodecError> {
        runtime_codec::decode_object(value, true, |object| {
            Ok(Self {
                provider: object.required("provider", &[])?,
                family: object.optional("family", &[])?,
                prompt_style: object.required("promptStyle", &[])?,
                tool_description_style: object.required("toolDescriptionStyle", &[])?,
                prefers_explicit_parallelism_hint: object
                    .required("prefersExplicitParallelismHint", &[])?,
                prefers_explicit_delegation_criteria: object
                    .required("prefersExplicitDelegationCriteria", &[])?,
                reasoning_continuity: object.required("reasoningContinuity", &[])?,
            })
        })
    }
}

