#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TraceMode {
    ScriptedExact,
    LiveContract,
}

enum EvalModelCapture {
    Scripted(ScriptedModelCapture),
    Live(LiveModelCapture),
}

impl EvalModelCapture {
    fn finish(self) -> Result<Vec<ModelRequest>, ProviderBehaviorEvalError> {
        match self {
            Self::Scripted(capture) => capture.finish(),
            Self::Live(capture) => capture.finish(),
        }
    }
}

struct EvalTaskBackend {
    process_context: RuntimeProcessContext,
    provider: Arc<dyn ModelProvider>,
    model: String,
    call_model: crate::types::provider::CallModel,
    capture: EvalModelCapture,
    trace_mode: TraceMode,
}

pub async fn run_scripted_suite(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    suite: &str,
    profiles: &[EvalProfile],
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    let traces = run_scripted_suite_tolerant(process_context, manifest, suite, profiles).await?;
    for trace in &traces {
        require_successful_trace(trace)?;
    }
    Ok(traces)
}

/// Run a complete fixed-contract suite while preserving ordinary score and
/// behavior misses as failed traces. Harness, fixture, execution, I/O, and
/// serialization failures remain hard errors.
pub async fn run_scripted_suite_tolerant(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    suite: &str,
    profiles: &[EvalProfile],
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    let names = manifest
        .suite(suite)
        .ok_or_else(|| ProviderBehaviorEvalError::UnknownSuite(suite.to_owned()))?;
    validate_requested_profile_coverage(manifest, names, profiles)?;
    run_scripted_rows_tolerant(process_context, manifest, names, profiles).await
}

/// Run exactly one fixed-contract task for an ordered subset of the profiles
/// declared by that task. Unlike [`run_scripted_suite`], score and behavior
/// misses are returned in the trace for Eval artifact accounting.
pub async fn run_scripted_task_tolerant(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    task_name: &str,
    profiles: &[EvalProfile],
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    let task = manifest.task(task_name)?;
    validate_requested_task_profiles(task, profiles)?;
    run_scripted_rows_tolerant(
        process_context,
        manifest,
        std::slice::from_ref(&task.name),
        profiles,
    )
    .await
}

async fn run_scripted_rows_tolerant(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    names: &[RuntimeString],
    profiles: &[EvalProfile],
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    let fixture = load_rust_scripted_adaptations(manifest)?;
    let adaptations = apply_rust_scripted_adaptations(manifest, names, &fixture)?;
    let mut scripted_request_matchers = scripted_request_matchers_for_suite(&fixture, names)?;
    scripted_request_matchers.retain(|(_, profile), _| profiles.contains(profile));
    let mut adaptation_runs = BTreeMap::<RuntimeString, usize>::new();
    let mut matcher_runs = BTreeSet::<(RuntimeString, EvalProfile)>::new();
    let mut traces = Vec::new();
    for name in names {
        let adaptation = adaptations.get(name);
        let task = match adaptation {
            Some(adaptation) => &adaptation.task,
            None => manifest.task(name)?,
        };
        for profile in profiles {
            if task.required_profiles.contains(profile) {
                let matcher_key = (name.clone(), *profile);
                let matchers = scripted_request_matchers.get(&matcher_key);
                if matchers.is_some() && !matcher_runs.insert(matcher_key.clone()) {
                    return Err(ProviderBehaviorEvalError::Adaptation(format!(
                        "scripted request matchers for {matcher_key:?} ran more than once"
                    )));
                }
                let trace = run_scripted_task_raw(
                    process_context,
                    task,
                    *profile,
                    matchers.map(Vec::as_slice),
                )
                .await?;
                if let Some(adaptation) = adaptation {
                    validate_adapted_trace(adaptation, &trace)?;
                    *adaptation_runs.entry(name.clone()).or_default() += 1;
                }
                traces.push(trace);
            }
        }
    }
    for (name, adaptation) in &adaptations {
        let actual = adaptation_runs.get(name).copied().unwrap_or_default();
        let expected = adaptation
            .task
            .required_profiles
            .iter()
            .filter(|profile| profiles.contains(profile))
            .count();
        if actual != expected {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "adaptation {name:?} profile matrix was consumed {actual} times, expected {expected}"
            )));
        }
    }
    let expected_matcher_runs = scripted_request_matchers
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    if matcher_runs != expected_matcher_runs {
        return Err(ProviderBehaviorEvalError::Adaptation(format!(
            "scripted request matcher profile matrix was not consumed exactly once: expected {expected_matcher_runs:?}, got {matcher_runs:?}"
        )));
    }
    Ok(traces)
}

/// Run the protected live provider-core suite for one real provider profile.
/// Prelude turns are fixture-bound; all subsequent requests are delegated to
/// the supplied provider and captured in the returned traces.
pub async fn run_live_suite(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    suite: &str,
    profile: EvalProfile,
    provider: Arc<dyn ModelProvider>,
    model: &str,
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    if suite != "provider-core" {
        return Err(ProviderBehaviorEvalError::UnknownSuite(suite.to_owned()));
    }
    validate_live_provider(profile, provider.info(), model)?;
    let names = manifest
        .suite("provider-core")
        .ok_or_else(|| ProviderBehaviorEvalError::UnknownSuite("provider-core".to_owned()))?;
    let registry = load_live_prelude_registry(manifest)?;
    run_live_rows(
        process_context,
        manifest,
        names,
        profile,
        provider,
        model,
        &registry,
    )
    .await
}

/// Run one provider-core task against one real provider profile. Score and
/// behavior misses remain represented by a failed trace.
pub async fn run_live_task(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    task_name: &str,
    profile: EvalProfile,
    provider: Arc<dyn ModelProvider>,
    model: &str,
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    manifest.task(task_name)?;
    let core_names = manifest
        .suite("provider-core")
        .ok_or_else(|| ProviderBehaviorEvalError::UnknownSuite("provider-core".to_owned()))?;
    if !core_names
        .iter()
        .any(|name| runtime_eq_utf8(name, task_name))
    {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "live Eval task {task_name:?} is not a provider-core member"
        )));
    }
    validate_live_provider(profile, provider.info(), model)?;
    let registry = load_live_prelude_registry(manifest)?;
    run_live_rows(
        process_context,
        manifest,
        std::slice::from_ref(&manifest.task(task_name)?.name),
        profile,
        provider,
        model,
        &registry,
    )
    .await
}

async fn run_live_rows(
    process_context: &RuntimeProcessContext,
    manifest: &ProviderBehaviorManifest,
    names: &[RuntimeString],
    profile: EvalProfile,
    provider: Arc<dyn ModelProvider>,
    model: &str,
    registry: &LivePreludeRegistry,
) -> Result<Vec<ProviderBehaviorTrace>, ProviderBehaviorEvalError> {
    let mut traces = Vec::with_capacity(names.len());
    for name in names {
        let task = manifest.task(name)?;
        validate_requested_task_profiles(task, &[profile])?;
        let prelude = registry.profile(name, profile)?;
        if prelude.family != live_profile_family(profile)? {
            return Err(ProviderBehaviorEvalError::Adaptation(format!(
                "live prelude family drift for {name:?} / {profile:?}: {:?}",
                prelude.family,
            )));
        }
        traces.push(
            run_live_task_raw(
                process_context,
                task,
                profile,
                Arc::clone(&provider),
                model,
                prelude.turns.clone(),
            )
            .await?,
        );
    }
    Ok(traces)
}

fn validate_live_provider(
    profile: EvalProfile,
    provider_info: &ProviderInfo,
    model: &str,
) -> Result<(), ProviderBehaviorEvalError> {
    if model.trim().is_empty() {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(
            "live Eval model must be non-empty".to_owned(),
        ));
    }
    let (expected_provider, expected_prompt, expected_descriptions) = match profile {
        EvalProfile::Anthropic => (
            "anthropic",
            ProviderPromptStyle::AnthropicReminder,
            ProviderToolDescriptionStyle::Directive,
        ),
        EvalProfile::Openai => (
            "openai",
            ProviderPromptStyle::OpenAiDeveloper,
            ProviderToolDescriptionStyle::SchemaFirst,
        ),
        other => {
            return Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
                "live Eval supports only Anthropic or OpenAI, got {other:?}"
            )));
        }
    };
    let behavior =
        resolve_provider_behavior_profile(Some(provider_info), &RuntimeString::from_utf8(model));
    let expected_family = live_profile_family(profile)?;
    if provider_info.name != expected_provider
        || behavior.provider != expected_provider
        || behavior.family != Some(expected_family)
        || behavior.prompt_style != expected_prompt
        || behavior.tool_description_style != expected_descriptions
    {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
            "live provider/profile/facade mismatch: requested={profile:?}, provider={:?}, model={model:?}, resolvedProvider={:?}, resolvedFamily={:?}, prompt={:?}, descriptions={:?}",
            provider_info.name,
            behavior.provider,
            behavior.family,
            behavior.prompt_style,
            behavior.tool_description_style
        )));
    }
    Ok(())
}

async fn run_live_task_raw(
    process_context: &RuntimeProcessContext,
    task: &TaskContract,
    profile: EvalProfile,
    provider: Arc<dyn ModelProvider>,
    model: &str,
    prelude: Vec<Vec<ModelStreamEvent>>,
) -> Result<ProviderBehaviorTrace, ProviderBehaviorEvalError> {
    let profile_contract = task.profiles.get(&profile).ok_or_else(|| {
        ProviderBehaviorEvalError::ProfileCoverage(format!(
            "{:?} has no {profile:?} profile contract",
            task.name
        ))
    })?;
    let capture = LiveModelCapture::new(prelude.len());
    let call_model =
        recording_live_call_model(Arc::clone(&provider), prelude, model, capture.clone())?;
    run_task_raw(
        task,
        profile,
        profile_contract,
        EvalTaskBackend {
            process_context: process_context.clone(),
            provider,
            model: model.to_owned(),
            call_model,
            capture: EvalModelCapture::Live(capture),
            trace_mode: TraceMode::LiveContract,
        },
    )
    .await
}

fn require_successful_trace(
    trace: &ProviderBehaviorTrace,
) -> Result<(), ProviderBehaviorEvalError> {
    if trace.result.success {
        return Ok(());
    }
    Err(ProviderBehaviorEvalError::Task(format!(
        "{:?} / {:?} failed: score_success={}, final_text={:?}, behavior_failures={:?}, side_effects={:?}",
        trace.task.name,
        trace.run.profile,
        trace.result.score_success,
        trace.final_text,
        trace.result.behavior_failures,
        trace.side_effects
    )))
}

fn validate_requested_profile_coverage(
    manifest: &ProviderBehaviorManifest,
    names: &[RuntimeString],
    profiles: &[EvalProfile],
) -> Result<(), ProviderBehaviorEvalError> {
    if profiles.is_empty() {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(
            "at least one profile is required".to_owned(),
        ));
    }
    let unique = profiles.iter().copied().collect::<BTreeSet<_>>();
    if unique.len() != profiles.len() {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(
            "requested profiles contain duplicates".to_owned(),
        ));
    }
    for name in names {
        let task = manifest.task(name)?;
        let requested = profiles
            .iter()
            .copied()
            .filter(|profile| task.required_profiles.contains(profile))
            .collect::<BTreeSet<_>>();
        let required = task
            .required_profiles
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if requested != required {
            return Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
                "{name:?} requires {required:?}, requested {requested:?}"
            )));
        }
    }
    let mut seen_required = BTreeSet::new();
    let mut exact_order = Vec::new();
    for name in names {
        for profile in &manifest.task(name)?.required_profiles {
            if seen_required.insert(*profile) {
                exact_order.push(*profile);
            }
        }
    }
    if profiles != exact_order {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
            "suite requires exact ordered profile matrix {exact_order:?}, got {profiles:?}"
        )));
    }
    Ok(())
}

fn validate_requested_task_profiles(
    task: &TaskContract,
    profiles: &[EvalProfile],
) -> Result<(), ProviderBehaviorEvalError> {
    if profiles.is_empty() {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(
            "at least one profile is required".to_owned(),
        ));
    }
    let unique = profiles.iter().copied().collect::<BTreeSet<_>>();
    if unique.len() != profiles.len() {
        return Err(ProviderBehaviorEvalError::ProfileCoverage(
            "requested profiles contain duplicates".to_owned(),
        ));
    }
    for profile in profiles {
        if !task.required_profiles.contains(profile) || !task.profiles.contains_key(profile) {
            return Err(ProviderBehaviorEvalError::ProfileCoverage(format!(
                "{:?} does not declare requested profile {profile:?}",
                task.name
            )));
        }
    }
    Ok(())
}

async fn run_scripted_task_raw(
    process_context: &RuntimeProcessContext,
    task: &TaskContract,
    profile: EvalProfile,
    request_matchers: Option<&[ScriptedRequestMatcher]>,
) -> Result<ProviderBehaviorTrace, ProviderBehaviorEvalError> {
    let profile_contract = task.profiles.get(&profile).ok_or_else(|| {
        ProviderBehaviorEvalError::ProfileCoverage(format!(
            "{:?} has no {profile:?} scripted contract",
            task.name
        ))
    })?;
    let profile_contract =
        migrate_required_subagent_scripted_profile(&task.name, profile, profile_contract)
            .map_err(ProviderBehaviorEvalError::Task)?;
    let capture =
        ScriptedModelCapture::new(profile_contract.scripted_turns.len(), request_matchers)?;
    let call_model =
        captured_scripted_call_model(profile_contract.scripted_turns.clone(), capture.clone());
    let provider: Arc<dyn ModelProvider> = Arc::new(ScriptedProvider {
        info: profile_contract.provider_info.clone(),
    });
    run_task_raw(
        task,
        profile,
        &profile_contract,
        EvalTaskBackend {
            process_context: process_context.clone(),
            provider,
            model: eval_runtime_scalar(&profile_contract.model, "scripted profile model")?,
            call_model,
            capture: EvalModelCapture::Scripted(capture),
            trace_mode: TraceMode::ScriptedExact,
        },
    )
    .await
}

async fn run_task_raw(
    task: &TaskContract,
    profile: EvalProfile,
    profile_contract: &TaskProfileContract,
    backend: EvalTaskBackend,
) -> Result<ProviderBehaviorTrace, ProviderBehaviorEvalError> {
    let _environment_lock = EVAL_ENV_LOCK.lock().await;
    let task_name = eval_runtime_scalar(&task.name, "task name")?;
    let task_prompt = eval_runtime_scalar(&task.prompt, "task prompt")?;
    let workspace = EvalWorkspace::create(&task_name)?;
    let _environment = EvalEnvironment::install(workspace.path())?;
    apply_setup(workspace.path(), &task.setup)?;
    let before_files = snapshot_files(workspace.path())?;
    let expected_before = expected_setup_files(&task.setup);
    if before_files != expected_before {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "{:?} setup snapshot mismatch: expected {expected_before:?}, got {before_files:?}",
            task.name
        )));
    }

    let EvalTaskBackend {
        process_context,
        provider,
        model,
        call_model,
        capture,
        trace_mode,
    } = backend;
    let provider_info = provider.info().clone();
    let mut deps = EngineDepsOverrides {
        call_model: Some(call_model),
        ..EngineDepsOverrides::default()
    };
    if trace_mode == TraceMode::ScriptedExact {
        let uuid_index = Arc::new(AtomicUsize::new(0));
        let now_index = Arc::new(AtomicU64::new(0));
        let uuid = {
            let uuid_index = Arc::clone(&uuid_index);
            Arc::new(move || {
                format!(
                    "fixture-{:06}",
                    uuid_index.fetch_add(1, Ordering::SeqCst) + 1
                )
            })
        };
        let now = {
            let now_index = Arc::clone(&now_index);
            Arc::new(move || {
                1_736_942_400_000_i64 + now_index.fetch_add(1, Ordering::SeqCst) as i64
            })
        };
        deps.uuid = Some(uuid);
        deps.now = Some(now);
    }
    let tools = match build_eval_tools(task)? {
        Some(tools) => Some(tools),
        None if task.config.code_mode => {
            // The session config key that once swapped in the code-mode
            // surface is retired, so the adapted replay provides the declared
            // exec/wait pair explicitly on top of the default builtin catalog
            // that the contract comparison derives. The cell registry mirrors
            // the exposed surface so a scripted cell can nest the declared
            // tool calls through the same dispatch as a normal call.
            let runtime = create_code_mode_tools();
            let mut surface = build_eval_tools_for_replay(task)?;
            surface.push(runtime.exec.clone());
            surface.push(runtime.wait.clone());
            runtime.set_tool_registry(surface.clone());
            Some(surface)
        }
        None => None,
    };
    let hooks = build_eval_hooks(&task.hooks)?;
    let (approval_policy, sandbox_mode) = match task.permission_mode {
        EvalPermissionMode::BypassPermissions => ("never", "danger-full-access"),
        EvalPermissionMode::Default => ("on-request", "read-only"),
    };
    let agent = Agent::new(AgentOptions {
        process_context: process_context.clone(),
        provider,
        config: Some(json!({
            "model": model,
            "approval_policy": approval_policy,
            "sandbox_mode": sandbox_mode,
            "approvals_reviewer": "user",
            "codeMode": task.config.code_mode,
            "editedFiles": task.config.edited_files,
            "fork": task.config.fork,
        })),
        tools,
        web_fetch_page: None,
        browser_runtime: None,
        capability_roots: Vec::new(),
        cwd: Some(path_string(workspace.path())?),
        deps,
        compactor: None,
        approval_handler: None,
        approval_reviewer: None,
        elicit_handler: None,
        credential_store: None,
        hooks,
        observer: Some(None),
        logger: None,
        pricing: None,
        agents: None,
        include_default_agents: None,
        skills: None,
        output_styles: None,
        workflows: None,
        mcp_catalog: None,
        // Keep provider-behavior recordings independent of an ambient packaged
        // plugin marketplace. `Some(|| None)` suppresses the default env lookup.
        plugin_catalog: Some(Arc::new(|| None)),
        lsp_servers: None,
        agent_memory: None,
        mcp_clients: None,
        mcp_server_configs: Vec::new(),
        mcp_tools: None,
        refresh_tools: None,
        system_prompt_provider: None,
        plugins: Vec::new(),
        plugin_load_report: None,
    });
    let session = agent.start_session(StartSessionOptions {
        id: Some(RuntimeString::from_utf8(EVAL_MAIN_SESSION_ID)),
        permission_mode: Some(eval_permission_mode(task.permission_mode)),
        ..StartSessionOptions::default()
    });
    let output_schema = task
        .output_schema
        .as_ref()
        .map(|schema| eval_runtime_json_scalar(schema, "task output schema"))
        .transpose()?
        .map(|schema| {
            schema.as_object().cloned().ok_or_else(|| {
                ProviderBehaviorEvalError::Task("task output schema must be an object".to_owned())
            })
        })
        .transpose()?;
    let mut events = session
        .run_streamed(
            Input::Text(task_prompt.into()),
            TurnOptions {
                output_schema,
                ..TurnOptions::default()
            },
        )
        .events;
    let mut engine_events = Vec::new();
    let mut turn_terminal_count = 0_usize;
    let mut turn_failure = None;
    let mut turn_stop_reason = None;
    while let Some(event) = events.next().await {
        match &event {
            EngineEvent::TurnCompleted { stop_reason, .. } => {
                turn_terminal_count += 1;
                turn_stop_reason = Some(*stop_reason);
            }
            EngineEvent::TurnFailed { error, .. } => {
                turn_terminal_count += 1;
                turn_failure = Some(format!(
                    "{:?}: {}",
                    error.code,
                    runtime_diagnostic(&error.message)
                ));
            }
            _ => {}
        }
        engine_events.push(runtime_codec::encode_value(&event)?);
    }
    validate_raw_tool_event_turn_ownership(&engine_events)?;
    let history = session
        .history()
        .into_iter()
        .map(|message| runtime_codec::encode_value(&message))
        .collect::<Result<Vec<_>, _>>()?;
    session.dispose().await;
    let after_files = snapshot_files(workspace.path())?;
    let model_requests = capture
        .finish()?
        .into_iter()
        .map(|request| runtime_codec::encode_value(&request))
        .collect::<Result<Vec<_>, _>>()?;
    if model_requests.is_empty() {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "{:?} / {profile:?} emitted no model requests",
            task.name
        )));
    }
    if turn_terminal_count != 1 {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "{:?} / {profile:?} emitted {turn_terminal_count} turn terminal events, expected exactly one",
            task.name
        )));
    }
    if let Some(failure) = turn_failure {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "{:?} / {profile:?} turn failed: {failure}",
            task.name
        )));
    }
    let turn_stop_reason = turn_stop_reason.ok_or_else(|| {
        ProviderBehaviorEvalError::Task(format!(
            "{:?} / {profile:?} emitted no turn.completed stopReason",
            task.name
        ))
    })?;
    let final_text = validate_and_reconstruct_stream_text(&engine_events, &history)?;

    let run_model = RuntimeString::from_utf8(&model);
    let run = trace_run(profile, &provider_info, &run_model)?;
    let model_visible_tool_uses = visible_calls_from_history(&history)?;
    let normalized_internal_calls = normalized_calls(
        &model_visible_tool_uses,
        &run,
        &profile_contract.visible_name_overrides,
    )?;
    let side_effects = derive_side_effects(&engine_events, &before_files, &after_files)?;
    let score_success =
        score_rules(&process_context, &task.score, workspace.path(), &final_text).await?;
    let behavior_failures = evaluate_behavior(
        &task.behavior,
        &run,
        &final_text,
        &history,
        &model_requests,
        &model_visible_tool_uses,
        &side_effects,
        &engine_events,
    )
    .into_iter()
    .map(RuntimeString::from)
    .collect::<Vec<_>>();
    let behavior_success = behavior_failures.is_empty();
    let result = TraceResult {
        success: trace_result_success(turn_stop_reason, score_success, behavior_success),
        score_success,
        behavior_success,
        behavior_failures,
    };
    let mut trace = ProviderBehaviorTrace {
        schema_version: 1,
        task: TraceTask {
            name: task.name.clone(),
            description: task.description.clone(),
            prompt: task.prompt.clone(),
        },
        run,
        normalization: TraceNormalization {
            workspace_root: RuntimeString::from_utf8("$WORKSPACE"),
            project_slug_token: RuntimeString::from_utf8("$PROJECT_SLUG"),
            non_contract_time_pointers: Vec::new(),
            non_contract_host_pointers: Vec::new(),
            non_contract_parallel_event_pointers: Vec::new(),
            non_contract_parallel_uuid_pointers: Vec::new(),
        },
        result,
        final_text,
        model_requests,
        model_visible_tool_uses,
        normalized_internal_calls,
        engine_events,
        history,
        before_files: before_files.into_iter().collect(),
        after_files: after_files.into_iter().collect(),
        side_effects,
    };
    normalize_provider_behavior_trace(&mut trace, task, workspace.path(), trace_mode)?;
    Ok(trace)
}

static EVAL_WORKSPACE_COUNTER: AtomicU64 = AtomicU64::new(0);
static EVAL_ENV_LOCK: LazyLock<tokio::sync::Mutex<()>> =
    LazyLock::new(|| tokio::sync::Mutex::new(()));

struct EvalEnvironment {
    #[cfg(test)]
    _config_env_guard: std::sync::MutexGuard<'static, ()>,
    previous_config_dir: Option<std::ffi::OsString>,
    previous_task_list_id: Option<std::ffi::OsString>,
}

impl EvalEnvironment {
    fn install(workspace: &Path) -> Result<Self, ProviderBehaviorEvalError> {
        #[cfg(test)]
        let config_env_guard = crate::test_support::CONFIG_ENV_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let previous_config_dir = std::env::var_os("KLAUS_CONFIG_DIR");
        let previous_task_list_id = std::env::var_os("KLAUS_TASK_LIST_ID");
        crate::runtime_process::set_process_environment_var(
            "KLAUS_CONFIG_DIR",
            workspace.join(".klaus-config"),
        );
        crate::runtime_process::remove_process_environment_var("KLAUS_TASK_LIST_ID");
        Ok(Self {
            #[cfg(test)]
            _config_env_guard: config_env_guard,
            previous_config_dir,
            previous_task_list_id,
        })
    }
}

impl Drop for EvalEnvironment {
    fn drop(&mut self) {
        match self.previous_config_dir.take() {
            Some(value) => {
                crate::runtime_process::set_process_environment_var("KLAUS_CONFIG_DIR", value)
            }
            None => crate::runtime_process::remove_process_environment_var("KLAUS_CONFIG_DIR"),
        }
        match self.previous_task_list_id.take() {
            Some(value) => {
                crate::runtime_process::set_process_environment_var("KLAUS_TASK_LIST_ID", value)
            }
            None => crate::runtime_process::remove_process_environment_var("KLAUS_TASK_LIST_ID"),
        }
    }
}

struct EvalWorkspace(PathBuf);

impl EvalWorkspace {
    fn create(task: &str) -> Result<Self, std::io::Error> {
        Self::create_from_candidates(|| {
            eval_workspace_candidate(task, EVAL_WORKSPACE_COUNTER.fetch_add(1, Ordering::SeqCst))
        })
    }

    fn create_from_candidates(
        mut next_candidate: impl FnMut() -> PathBuf,
    ) -> Result<Self, std::io::Error> {
        loop {
            let path = next_candidate();
            match std::fs::create_dir(&path) {
                Ok(()) => return Ok(Self(path)),
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(error) => return Err(error),
            }
        }
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

fn eval_workspace_candidate(task: &str, counter: u64) -> PathBuf {
    std::env::temp_dir().join(format!(
        "klaus-provider-behavior-{task}-{}-{counter}",
        std::process::id()
    ))
}

impl Drop for EvalWorkspace {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn path_string(path: &Path) -> Result<String, ProviderBehaviorEvalError> {
    path.to_str()
        .map(str::to_owned)
        .ok_or_else(|| ProviderBehaviorEvalError::Task("workspace path is not UTF-8".to_owned()))
}

fn safe_workspace_path(
    workspace: &Path,
    relative: &str,
) -> Result<PathBuf, ProviderBehaviorEvalError> {
    let path = Path::new(relative);
    if relative.contains('\0')
        || path.is_absolute()
        || path
            .components()
            .any(|part| matches!(part, std::path::Component::ParentDir))
    {
        return Err(ProviderBehaviorEvalError::Task(format!(
            "unsafe task path: {relative}"
        )));
    }
    Ok(workspace.join(path))
}

fn apply_setup(workspace: &Path, actions: &[SetupAction]) -> Result<(), ProviderBehaviorEvalError> {
    for action in actions {
        match action {
            SetupAction::CreateDir { path } => {
                let path = eval_runtime_scalar(path, "setup directory path")?;
                std::fs::create_dir_all(safe_workspace_path(workspace, &path)?)?;
            }
            SetupAction::WriteFile { path, content } => {
                let path = eval_runtime_scalar(path, "setup file path")?;
                let content = eval_runtime_scalar(content, "setup file content")?;
                let target = safe_workspace_path(workspace, &path)?;
                if let Some(parent) = target.parent() {
                    std::fs::create_dir_all(parent)?;
                }
                std::fs::write(target, content)?;
            }
        }
    }
    Ok(())
}

fn expected_setup_files(actions: &[SetupAction]) -> BTreeMap<RuntimeString, RuntimeString> {
    actions
        .iter()
        .filter_map(|action| match action {
            SetupAction::WriteFile { path, content } => Some((path.clone(), content.clone())),
            SetupAction::CreateDir { .. } => None,
        })
        .collect()
}

fn snapshot_files(
    root: &Path,
) -> Result<BTreeMap<RuntimeString, RuntimeString>, ProviderBehaviorEvalError> {
    fn visit(
        root: &Path,
        directory: &Path,
        out: &mut BTreeMap<RuntimeString, RuntimeString>,
    ) -> Result<(), ProviderBehaviorEvalError> {
        let mut entries = std::fs::read_dir(directory)?.collect::<Result<Vec<_>, _>>()?;
        entries.sort_by_key(std::fs::DirEntry::file_name);
        for entry in entries {
            let file_type = entry.file_type()?;
            let path = entry.path();
            let relative = path
                .strip_prefix(root)
                .map_err(|error| ProviderBehaviorEvalError::Task(error.to_string()))?;
            let relative = relative
                .to_str()
                .ok_or_else(|| {
                    ProviderBehaviorEvalError::Task("snapshot path is not UTF-8".to_owned())
                })?
                .replace(std::path::MAIN_SEPARATOR, "/");
            // The Eval config root lives inside the disposable workspace so
            // durable Task* calls cannot touch the developer's real config.
            // It is harness state, not a file the evaluated task edited.
            if relative == ".klaus-config" || relative.starts_with(".klaus-config/") {
                continue;
            }
            if relative.contains('\0') || file_type.is_symlink() {
                return Err(ProviderBehaviorEvalError::Task(format!(
                    "snapshot rejects unsafe path: {relative}"
                )));
            }
            if file_type.is_dir() {
                visit(root, &path, out)?;
            } else if file_type.is_file() {
                let bytes = std::fs::read(&path)?;
                if bytes.contains(&0) {
                    return Err(ProviderBehaviorEvalError::Task(format!(
                        "snapshot rejects NUL/non-text file: {relative}"
                    )));
                }
                let text = String::from_utf8(bytes).map_err(|_| {
                    ProviderBehaviorEvalError::Task(format!(
                        "snapshot rejects non-UTF8 file: {relative}"
                    ))
                })?;
                out.insert(RuntimeString::from(relative), RuntimeString::from(text));
            } else {
                return Err(ProviderBehaviorEvalError::Task(format!(
                    "snapshot rejects special file: {relative}"
                )));
            }
        }
        Ok(())
    }

    let mut files = BTreeMap::new();
    visit(root, root, &mut files)?;
    Ok(files)
}

fn eval_permission_mode(mode: EvalPermissionMode) -> ExternalPermissionMode {
    match mode {
        EvalPermissionMode::BypassPermissions => ExternalPermissionMode::BypassPermissions,
        EvalPermissionMode::Default => ExternalPermissionMode::Default,
    }
}

