    #[test]
    fn repl_description_migration_preserves_complete_catalogs_for_every_profile() {
        let source = pinned_source_repl_spec();
        assert_eq!(exact_runtime_json_sha256(&source), PRE_ADAPTIVE_REPL_SHA256);
        let sources = current_plan_source_catalogs();
        assert_eq!(sources.len(), 12);
        for (provider, model) in [
            ("anthropic", "claude-sonnet-5"),
            ("openai", "gpt-5.4-0305-global"),
            ("fake", "fake-model"),
        ] {
            let profile = resolve_provider_behavior_profile(
                Some(&ProviderInfo {
                    name: provider.into(),
                    base_url: None,
                    env_key: None,
                    default_model: model.into(),
                }),
                &model.into(),
            );
            let targets = render_tool_specs_for_behavior(&[current_repl_spec()], &profile);
            let target = runtime_codec::encode_value(&targets[0]).unwrap();
            assert_eq!(exact_runtime_json_sha256(&target), ADAPTIVE_REPL_SHA256);
            for mut request in sources.clone() {
                let before = request.clone();
                migrate_baseline_repl_raw_spec(&mut request, &targets, "unit fixture").unwrap();
                let once = request.clone();
                migrate_baseline_repl_raw_spec(&mut request, &targets, "unit fixture").unwrap();
                assert_eq!(request, once, "the approved target is idempotent");
                let migrated = request["tools"]
                    .as_array_mut()
                    .unwrap()
                    .iter_mut()
                    .find(|tool| runtime_json_field_eq(tool, "name", "REPL"))
                    .unwrap();
                assert_eq!(&*migrated, &target);
                *migrated.get_mut("description").unwrap() = source["description"].clone();
                assert_eq!(request, before, "only the approved description changes");
            }
        }
    }

