    #[test]
    fn retired_plan_tool_migration_preserves_unrelated_catalog_entries() {
        let catalogs = current_plan_source_catalogs();
        assert_eq!(catalogs.len(), 12);
        for mut request in catalogs {
            let mut expected = request.clone();
            let tools = expected["tools"].as_array_mut().unwrap();
            let before = tools.len();
            tools.retain(|tool| {
                !tool
                    .get("name")
                    .and_then(RuntimeJson::as_str)
                    .is_some_and(is_retired_plan_tool_name)
            });
            assert!(matches!(before - tools.len(), 1 | 3));
            migrate_baseline_retired_plan_tool_specs(&mut request, &[], "unit fixture").unwrap();
            assert_eq!(request, expected);
            migrate_baseline_retired_plan_tool_specs(&mut request, &[], "unit fixture").unwrap();
            assert_eq!(request, expected, "retirement is idempotent");
        }
        for source in [
            exact_pre_create_plan_enter_plan_mode_raw_spec(),
            exact_final_enter_plan_mode_raw_spec(),
            exact_pre_plan_file_exit_plan_mode_raw_spec(),
            exact_optional_plan_exit_plan_mode_raw_spec(),
        ] {
            let mut request = exact_json!({"tools": []});
            request["tools"].as_array_mut().unwrap().push(source);
            migrate_baseline_retired_plan_tool_specs(&mut request, &[], "unit fixture").unwrap();
            assert_eq!(request, exact_json!({"tools": []}));
        }
    }

