    #[test]
    fn ordinary_orchestration_migration_rejects_drift_without_partial_updates() {
        let target = exact_ordinary_orchestration_target();
        let base = exact_json!({
            "effort": null,
            "system": [
                {"name": "base", "text": "Keep this", "cacheable": true, "cacheScope": "global"},
                {"name": "provider-behavior:openai-developer", "text": "Keep suffix"}
            ],
            "marker": "Keep this too"
        });
        let mut valid = base.clone();
        migrate_baseline_ordinary_orchestration(&mut valid, &target, "fixture").unwrap();
        let system = valid.get("system").unwrap().as_array().unwrap();
        assert_eq!(
            system[0],
            base.get("system").unwrap().as_array().unwrap()[0]
        );
        assert_eq!(system[1], target);
        assert_eq!(
            system[2],
            base.get("system").unwrap().as_array().unwrap()[1]
        );
        let once = valid.clone();
        migrate_baseline_ordinary_orchestration(&mut valid, &target, "fixture").unwrap();
        assert_eq!(valid, once);
        let mut no_effort = base.clone();
        no_effort.as_object_mut().unwrap().remove("effort");
        migrate_baseline_ordinary_orchestration(&mut no_effort, &target, "fixture").unwrap();

        let mut altered_targets = Vec::new();
        for (key, value) in [
            ("text", RuntimeJson::String("Unapproved".into())),
            ("cacheable", RuntimeJson::Bool(true)),
            ("cacheScope", RuntimeJson::String("global".into())),
            ("extra", RuntimeJson::Null),
        ] {
            let mut altered = target.clone();
            altered.as_object_mut().unwrap().insert(key, value);
            altered_targets.push(altered);
        }
        for altered in &altered_targets {
            let mut request = base.clone();
            assert!(
                migrate_baseline_ordinary_orchestration(&mut request, altered, "fixture").is_err()
            );
            assert_eq!(request, base);
        }
        let mut requests = Vec::new();
        let mut effort = base.clone();
        *effort.get_mut("effort").unwrap() = RuntimeJson::String("ultra".into());
        requests.push(effort);
        let mut duplicate = once.clone();
        duplicate
            .get_mut("system")
            .unwrap()
            .as_array_mut()
            .unwrap()
            .insert(1, target.clone());
        requests.push(duplicate);
        let mut misplaced = base.clone();
        misplaced
            .get_mut("system")
            .unwrap()
            .as_array_mut()
            .unwrap()
            .push(target.clone());
        requests.push(misplaced);
        for altered in altered_targets {
            let mut request = once.clone();
            request.get_mut("system").unwrap().as_array_mut().unwrap()[1] = altered;
            requests.push(request);
        }
        for mut request in requests {
            let before = request.clone();
            assert!(
                migrate_baseline_ordinary_orchestration(&mut request, &target, "fixture").is_err()
            );
            assert_eq!(request, before);
        }
    }

