    fn current_plan_source_catalogs() -> Vec<RuntimeJson> {
        let fixture =
            include_str!("../../tests/fixtures/provider_behavior/v1/baseline.contract.jsonl");
        let blobs = parse_baseline_contract_header(fixture.lines().next().unwrap()).unwrap();
        CURRENT_PLAN_SOURCE_CATALOGS
            .iter()
            .map(|(digest, _)| {
                let mut request = RuntimeObject::new();
                request.insert("tools", blobs.get(&rs(digest)).unwrap().clone());
                RuntimeJson::Object(request)
            })
            .collect()
    }

    #[test]
    fn current_plan_raw_migration_accepts_only_the_twelve_complete_source_catalogs() {
        let targets = current_plan_runtime_specs();
        let sources = current_plan_source_catalogs();
        assert_eq!(sources.len(), 12);
        for (mut request, (_, insertion_index)) in
            sources.into_iter().zip(CURRENT_PLAN_SOURCE_CATALOGS)
        {
            let source = request.clone();
            migrate_baseline_current_plan_raw_specs(
                &mut request,
                &targets,
                ProviderPromptStyle::Generic,
                "unit fixture",
            )
            .expect("the pinned complete catalog must migrate");
            let tools = request.get_mut("tools").unwrap().as_array_mut().unwrap();
            let inserted = tools.remove(*insertion_index);
            assert_eq!(inserted, runtime_codec::encode_value(&targets[2]).unwrap());
            for tool in tools.iter_mut() {
                for name in ["TaskCreate", "TaskList"] {
                    if runtime_json_field_eq(tool, "name", name) {
                        *tool.get_mut("description").unwrap() =
                            exact_pre_current_plan_raw_spec(name)
                                .get("description")
                                .unwrap()
                                .clone();
                    }
                }
            }
            assert_eq!(request, source, "no other source field or order may change");
        }
    }

    #[test]
    fn current_plan_raw_migration_rejects_source_description_schema_and_toolset_drift() {
        let source = current_plan_source_catalogs().remove(0);
        let targets = current_plan_runtime_specs();
        for mutation in 0..12 {
            let mut request = source.clone();
            let tools = request.get_mut("tools").unwrap().as_array_mut().unwrap();
            let index = tools
                .iter()
                .position(|tool| runtime_json_field_eq(tool, "name", "TaskCreate"))
                .unwrap();
            match mutation {
                0 => *tools[index].get_mut("description").unwrap() = RuntimeJson::from("drift"),
                1 => *tools[index].get_mut("inputSchema").unwrap() = RuntimeJson::Null,
                2 => {
                    tools[index]
                        .as_object_mut()
                        .unwrap()
                        .insert("unknown", RuntimeJson::Bool(true));
                }
                3 => {
                    tools.remove(index);
                }
                4 => tools.push(tools[index].clone()),
                5 => tools.push(runtime_codec::encode_value(&targets[2]).unwrap()),
                6 => tools.swap(0, 1),
                7 => {
                    *tools[0].get_mut("description").unwrap() = RuntimeJson::from("unrelated drift")
                }
                8 => *tools[0].get_mut("inputSchema").unwrap() = RuntimeJson::Null,
                9 => {
                    tools.remove(0);
                }
                10 => tools.retain(|tool| {
                    !CURRENT_PLAN_TARGET_SPECS
                        .iter()
                        .any(|(name, _)| runtime_json_field_eq(tool, "name", name))
                }),
                11 => {
                    let list = tools
                        .iter_mut()
                        .find(|tool| runtime_json_field_eq(tool, "name", "TaskList"))
                        .unwrap();
                    *list.get_mut("description").unwrap() = RuntimeJson::from("list drift");
                }
                _ => unreachable!(),
            }
            let before = request.clone();
            let error = migrate_baseline_current_plan_raw_specs(
                &mut request,
                &targets,
                ProviderPromptStyle::Generic,
                "unit fixture",
            )
            .expect_err("unrecognized source drift must fail closed");
            assert!(error.contains("source raw catalog drifted"), "{error}");
            assert_eq!(
                request, before,
                "failed validation must not partially migrate"
            );
        }
    }

    #[test]
    fn current_plan_raw_migration_rejects_target_description_schema_and_membership_drift() {
        for mutation in 0..9 {
            let mut targets = current_plan_runtime_specs();
            match mutation {
                0..=2 => targets[mutation].description = rs("target drift"),
                3..=5 => targets[mutation - 3].input_schema = RuntimeJson::Null,
                6 => {
                    targets.remove(0);
                }
                7 => targets.push(targets[2].clone()),
                8 => targets.clear(),
                _ => unreachable!(),
            }
            let mut request = current_plan_source_catalogs().remove(0);
            let before = request.clone();
            migrate_baseline_current_plan_raw_specs(
                &mut request,
                &targets,
                ProviderPromptStyle::Generic,
                "unit fixture",
            )
            .expect_err("runtime target drift must fail closed independently of source");
            assert_eq!(request, before);
        }
        let mut explicit_registry =
            runtime_json::parse(&rs(r#"{"tools":[{"name":"custom"}]}"#)).unwrap();
        let before = explicit_registry.clone();
        migrate_baseline_current_plan_raw_specs(
            &mut explicit_registry,
            &[],
            ProviderPromptStyle::Generic,
            "explicit registry",
        )
        .unwrap();
        assert_eq!(explicit_registry, before);
    }

