    fn team_create_request(source: RuntimeJson) -> RuntimeJson {
        let tools = LEGACY_TS_ANTHROPIC_TOOL_NAMES
            .iter()
            .map(|name| {
                if *name == "TeamCreate" {
                    return source.clone();
                }
                let mut tool = RuntimeObject::new();
                tool.insert("name", RuntimeJson::String(RuntimeString::from(*name)));
                RuntimeJson::Object(tool)
            })
            .collect::<Vec<_>>();
        let mut request = RuntimeObject::new();
        request.insert("tools", RuntimeJson::Array(tools));
        RuntimeJson::Object(request)
    }

    fn team_create_canonical_specs(target_index: usize) -> Vec<ToolSpec> {
        let mut specs = (0..target_index)
            .map(|index| ToolSpec {
                name: RuntimeString::from(format!("before-{index}")),
                description: RuntimeString::default(),
                input_schema: RuntimeJson::Object(RuntimeObject::new()),
                kind: ToolSpecKind::Function,
                format: None,
            })
            .collect::<Vec<_>>();
        specs.push(cc_authoritative_team_create_spec());
        specs
    }

