    #[test]
    fn fixed_ts_team_create_raw_adapter_rejects_value_unknown_default_order_and_position_drift() {
        let authoritative = cc_authoritative_team_create_spec();
        let canonical = team_create_canonical_specs(1);

        let mut value_drift = exact_legacy_ts_team_create_raw_spec();
        *value_drift.get_mut("description").unwrap() = RuntimeJson::String(rs("drift"));
        let error = migrate_baseline_team_create_raw_spec(
            &mut team_create_request(value_drift),
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .expect_err("field-value drift must fail closed");
        assert!(error.contains("legacy source raw contract drifted"));

        let mut unknown = exact_legacy_ts_team_create_raw_spec();
        unknown
            .as_object_mut()
            .unwrap()
            .insert("unknown", RuntimeJson::Bool(true));
        assert!(migrate_baseline_team_create_raw_spec(
            &mut team_create_request(unknown),
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .unwrap_err()
        .contains("legacy source raw contract drifted"));

        let mut explicit_default = exact_legacy_ts_team_create_raw_spec();
        explicit_default
            .as_object_mut()
            .unwrap()
            .insert("kind", RuntimeJson::String(RuntimeString::from("function")));
        assert!(migrate_baseline_team_create_raw_spec(
            &mut team_create_request(explicit_default),
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .unwrap_err()
        .contains("legacy source raw contract drifted"));

        let reordered = runtime_json::parse(&RuntimeString::from(
            r#"{"name":"TeamCreate","description":"Create or join a swarm team and register this agent as a peer, so teammates can list and message each other.","inputSchema":{"additionalProperties":false,"properties":{"peer":{"description":"This agent's peer name within the team (defaults to a session-derived name).","type":"string"},"team":{"description":"Team name to create or join. Required if this session has no team yet.","type":"string"}},"type":"object"}}"#,
        ))
        .unwrap();
        assert!(migrate_baseline_team_create_raw_spec(
            &mut team_create_request(reordered),
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .unwrap_err()
        .contains("legacy source raw contract drifted"));

        let mut reordered_catalog = team_create_request(exact_legacy_ts_team_create_raw_spec());
        reordered_catalog
            .pointer_mut("/tools")
            .and_then(RuntimeJson::as_array_mut)
            .unwrap()
            .swap(27, 28);
        let error = migrate_baseline_team_create_raw_spec(
            &mut reordered_catalog,
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .expect_err("catalog position drift must fail closed");
        assert!(error.contains("catalog order drifted"));

        let already_target = runtime_codec::encode_value(&authoritative).unwrap();
        assert!(migrate_baseline_team_create_raw_spec(
            &mut team_create_request(already_target),
            &canonical,
            &authoritative,
            "unit fixture",
        )
        .unwrap_err()
        .contains("legacy source raw contract drifted"));
    }

