    #[test]
    fn fixed_ts_team_create_migration_validates_all_100_signed_rows() {
        let fixture =
            include_str!("../../tests/fixtures/provider_behavior/v1/baseline.contract.jsonl");
        let mut source_tool_count = 0_usize;
        let mut source_team_create_count = 0_usize;
        let mut source_tool_search_count = 0_usize;
        let mut source_task_create_count = 0_usize;
        let mut source_async_question_count = 0_usize;
        let mut optional_question_insertions = 0_usize;
        let mut deferred_message_slots = 0_usize;
        let mut source_request_count = 0_usize;
        let mut source_main_requests = 0_usize;
        let mut source_child_requests = 0_usize;
        let mut source_collaboration_parts = 0_usize;
        let mut retired_counts = RETIRED_PLAN_TOOL_NAMES
            .iter()
            .map(|name| (*name, 0_usize))
            .collect::<BTreeMap<_, _>>();
        for (index, value) in parse_baseline_contract(fixture)
            .expect("signed source contract must parse")
            .iter()
            .enumerate()
        {
            let row = parse_baseline_contract_row(value, index + 1)
                .expect("signed source row must parse before migration");
            for request in &row.trace.model_requests {
                let tools = request
                    .get("tools")
                    .and_then(RuntimeJson::as_array)
                    .expect("signed source request tools must be an array");
                source_tool_count += tools.len();
                source_request_count += 1;
                match signed_reference_request_role(request, &row.trace.history, "signed row")
                    .unwrap()
                {
                    "main" => source_main_requests += 1,
                    "child" => source_child_requests += 1,
                    _ => unreachable!("signed roles are exhaustive"),
                }
                source_collaboration_parts += request["system"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter(|part| runtime_json_field_eq(part, "name", "collaboration-mode"))
                    .count();
                for (name, count) in &mut retired_counts {
                    *count += tools
                        .iter()
                        .filter(|tool| runtime_json_field_eq(tool, "name", name))
                        .count();
                }
                let surfaced = request
                    .get("messages")
                    .and_then(RuntimeJson::as_array)
                    .is_some_and(|messages| {
                        messages
                            .iter()
                            .filter_map(|message| {
                                message
                                    .pointer("/nativeToolOutput/tools")
                                    .and_then(RuntimeJson::as_array)
                            })
                            .flatten()
                            .any(|tool| {
                                ["SendMessage", "send_message", "followup_task"]
                                    .iter()
                                    .any(|name| runtime_json_field_eq(tool, "name", name))
                            })
                    });
                if !surfaced {
                    deferred_message_slots +=
                        tools
                            .iter()
                            .filter(|tool| {
                                [SUBAGENT_NATIVE_MESSAGE_SOURCE,
                        "0afb20d1acc34b2db34b7cdb5752afec3369f2ab8f3dd8c600d46a07319aea20",
                        "4b8e2ff166eb3c456351f1bc74ed4e29e447cf8919c199ae709942967b5169d6"]
                            .contains(&exact_runtime_json_sha256(tool).as_str())
                            })
                            .count();
                }
                source_team_create_count += tools
                    .iter()
                    .filter(|tool| runtime_json_field_eq(tool, "name", "TeamCreate"))
                    .count();
                source_tool_search_count += tools
                    .iter()
                    .filter(|tool| runtime_json_field_eq(tool, "name", "tool_search"))
                    .count();
                source_task_create_count += tools
                    .iter()
                    .filter(|tool| runtime_json_field_eq(tool, "name", "TaskCreate"))
                    .count();
                source_async_question_count += tools
                    .iter()
                    .filter(|tool| runtime_json_field_eq(tool, "name", "ask_user_async"))
                    .count();
                // These signed catalogs predate optional questions; each
                // ask_user catalog gains one ask_user_async tool.
                optional_question_insertions += tools
                    .iter()
                    .filter(|tool| runtime_json_field_eq(tool, "name", "ask_user"))
                    .count();
            }
        }
        assert_eq!(source_tool_count, 9455);
        assert_eq!(source_request_count, 271);
        assert_eq!(source_main_requests, 250);
        assert_eq!(source_child_requests, 21);
        assert_eq!(source_collaboration_parts, 0);
        assert_eq!(retired_counts["enter_plan_mode"], 208);
        assert_eq!(retired_counts["exit_plan_mode"], 208);
        assert_eq!(retired_counts["suggest_execution_mode"], 211);
        assert_eq!(retired_counts["create_plan"], 0);
        assert_eq!(source_team_create_count, 0);
        assert_eq!(source_tool_search_count, 232);
        assert_eq!(source_task_create_count, 211);
        assert_eq!(source_async_question_count, 0);
        assert_eq!(optional_question_insertions, 211);
        assert_eq!(deferred_message_slots, 281);

        let traces = FIXED_TS_CONTRACT_TRACES
            .as_ref()
            .expect("all baseline rows must pass raw TeamCreate migration");
        assert_eq!(traces.len(), 100);
        let mut migrated_main_requests = 0_usize;
        let mut migrated_child_requests = 0_usize;
        for trace in traces.values() {
            let info = ProviderInfo {
                name: trace.run.provider_info.name.clone(),
                base_url: None,
                env_key: None,
                default_model: trace.run.provider_info.default_model.clone(),
            };
            let profile = resolve_provider_behavior_profile(Some(&info), &trace.run.model);
            let source = signed_subagent_source(&trace.task.name, &trace.run).unwrap();
            let source_history = source["history"].as_array().unwrap();
            let source_requests = source["modelRequests"].as_array().unwrap();
            assert_eq!(trace.model_requests.len(), source_requests.len());
            for (value, source_request) in trace.model_requests.iter().zip(source_requests) {
                let role =
                    signed_reference_request_role(source_request, source_history, "signed count")
                        .unwrap();
                let request: ModelRequest = runtime_codec::decode_value(value).unwrap();
                let prefix_len = request_history_prefix_len(&request, &trace.history).unwrap();
                assert_eq!(prefix_len.is_some(), role == "main");
                let progress = request
                    .tools
                    .iter()
                    .filter(|tool| tool.name == "update_plan")
                    .collect::<Vec<_>>();
                if role == "main" {
                    migrated_main_requests += 1;
                    assert_eq!(progress.len(), 1);
                    assert_eq!(
                        runtime_codec::encode_value(progress[0]).unwrap(),
                        fixed_default_update_plan_raw_spec()
                    );
                } else {
                    migrated_child_requests += 1;
                    assert!(progress.is_empty());
                }
                assert!(request
                    .tools
                    .iter()
                    .all(|tool| !is_retired_plan_tool_name(&tool.name)));
                let parts = request
                    .system
                    .iter()
                    .enumerate()
                    .filter(|(_, part)| part.name == "collaboration-mode")
                    .collect::<Vec<_>>();
                assert_eq!(parts.len(), 1);
                assert_eq!(
                    runtime_codec::encode_value(parts[0].1).unwrap(),
                    fixed_default_collaboration_raw_part()
                );
                let expected_reminder = expected_task_plan_reminder(
                    &request,
                    trace,
                    prefix_len,
                    &profile,
                    "signed planning catalog",
                )
                .unwrap();
                let actual_reminders = request
                    .system
                    .iter()
                    .filter(|part| part.name == "task-plan-reminder")
                    .collect::<Vec<_>>();
                assert_eq!(
                    actual_reminders,
                    expected_reminder.iter().collect::<Vec<_>>()
                );
                // Check the catalog migration before the independently verified
                // causal reminder is inserted, then check the complete final order.
                let mut before_reminder = request
                    .system
                    .iter()
                    .filter(|part| part.name != "task-plan-reminder")
                    .cloned()
                    .collect::<Vec<_>>();
                let permissions = before_reminder
                    .iter()
                    .enumerate()
                    .filter(|(_, part)| part.name == "permissions")
                    .map(|(index, _)| index)
                    .collect::<Vec<_>>();
                assert_eq!(permissions.len(), 1);
                assert!(permissions[0] > 0);
                assert_eq!(
                    before_reminder[permissions[0] - 1].name,
                    "collaboration-mode"
                );
                if let Some(reminder) = expected_reminder {
                    let anchor = before_reminder
                        .iter()
                        .position(|part| {
                            part.name == "multi-agent-role"
                                || part.name == "orchestration-mode"
                                || part.name == "total-tokens"
                                || part.name == "permissions"
                                || runtime_starts_with(
                                    &part.name,
                                    &RuntimeString::from("provider-behavior:"),
                                )
                        })
                        .unwrap_or(before_reminder.len());
                    before_reminder.insert(anchor, reminder);
                }
                assert_eq!(before_reminder, request.system);
            }
        }
        assert_eq!(migrated_main_requests, source_main_requests);
        assert_eq!(migrated_child_requests, source_child_requests);
        let migrated_tools = traces
            .values()
            .flat_map(|trace| &trace.model_requests)
            .flat_map(|request| {
                request
                    .get("tools")
                    .and_then(RuntimeJson::as_array)
                    .into_iter()
                    .flatten()
            })
            .count();
        let migrated_team_create = traces
            .values()
            .flat_map(|trace| &trace.model_requests)
            .flat_map(|request| {
                request
                    .get("tools")
                    .and_then(RuntimeJson::as_array)
                    .into_iter()
                    .flatten()
            })
            .filter(|tool| runtime_json_field_eq(tool, "name", "TeamCreate"))
            .count();
        let migrated_tool_search = traces
            .values()
            .flat_map(|trace| &trace.model_requests)
            .flat_map(|request| {
                request
                    .get("tools")
                    .and_then(RuntimeJson::as_array)
                    .into_iter()
                    .flatten()
            })
            .filter(|tool| runtime_json_field_eq(tool, "name", "tool_search"))
            .count();
        let migrated_async_questions = traces
            .values()
            .flat_map(|trace| &trace.model_requests)
            .flat_map(|request| {
                request
                    .get("tools")
                    .and_then(RuntimeJson::as_array)
                    .into_iter()
                    .flatten()
            })
            .filter(|tool| runtime_json_field_eq(tool, "name", "ask_user_async"))
            .count();
        // The refreshed source rows already carry the live deferred surface:
        // no TeamCreate remains and each former slot is tool_search. The raw
        // migration stays exercised by its focused legacy-shape tests above.
        // Each pinned current-plan catalog gains TaskWrite, and each eligible
        // default catalog also gains exactly one optional question tool. Retired
        // descriptors leave only their recorded slots; each Default root request
        // gains the fixed progress descriptor and children never gain it.
        // Native message descriptors retain their direct slots regardless of
        // historical search activation.
        assert_eq!(
            migrated_tools,
            source_tool_count + source_task_create_count + optional_question_insertions
                - retired_counts.values().sum::<usize>()
                + source_main_requests
        );
        assert_eq!(
            migrated_async_questions,
            source_async_question_count + optional_question_insertions
        );
        assert_eq!(migrated_team_create, 0);
        assert_eq!(migrated_tool_search, source_tool_search_count);
    }

    #[test]
    fn fixed_default_planning_contracts_pin_complete_parts_and_profile_rendering() {
        for (fixture, digest) in [
            (include_str!("../../tests/fixtures/instruction-request-matrix/default-questions-off-chat.json"),
             "bc9435763b4779739d9675dc0b8f1abfe91ad8432b7122e4f3f5343afe948afd"),
            (include_str!("../../tests/fixtures/instruction-request-matrix/default-questions-off-responses.json"),
             "e75a35e65c509a1177627451838824124cf9af141293aa3148a836eaf1e940a2"),
        ] {
            assert_eq!(sha256_hex(fixture.as_bytes()), digest);
            let fixture = runtime_json::parse(&RuntimeString::from(fixture)).unwrap();
            assert_eq!(fixed_default_update_plan_raw_spec(), fixture["modelRequests"][0]["tools"][3]);
            let parts = fixture["modelRequests"][0]["system"].as_array().unwrap().iter()
                .filter(|part| runtime_json_field_eq(part, "name", "collaboration-mode")).collect::<Vec<_>>();
            assert_eq!(parts.len(), 1);
            assert_eq!(&fixed_default_collaboration_raw_part(), parts[0]);
        }
        let fixture =
            include_str!("../../tests/fixtures/provider_behavior/v1/baseline.contract.jsonl");
        let mut profiles = BTreeMap::new();
        for (index, value) in parse_baseline_contract(fixture).unwrap().iter().enumerate() {
            let row = parse_baseline_contract_row(value, index + 1).unwrap();
            profiles.entry(row.profile).or_insert(row.trace.run);
        }
        assert_eq!(profiles.len(), 4);
        let progress: ToolSpec =
            runtime_codec::decode_value(&fixed_default_update_plan_raw_spec()).unwrap();
        for run in profiles.values() {
            let info = ProviderInfo {
                name: run.provider_info.name.clone(),
                base_url: None,
                env_key: None,
                default_model: run.provider_info.default_model.clone(),
            };
            let profile = resolve_provider_behavior_profile(Some(&info), &run.model);
            let rendered =
                render_tool_specs_for_behavior(std::slice::from_ref(&progress), &profile);
            assert_eq!(rendered.len(), 1);
            assert_eq!(
                runtime_codec::encode_value(&rendered[0]).unwrap(),
                fixed_default_update_plan_raw_spec()
            );
        }
    }

    #[test]
    fn default_planning_migration_rejects_ambiguous_mode_role_and_tool_predecessors() {
        let trace = fixed_ts_contract_trace("read-summarize", EvalProfile::Generic).unwrap();
        let baseline: ModelRequest = runtime_codec::decode_value(&trace.model_requests[0]).unwrap();
        let info = ProviderInfo {
            name: trace.run.provider_info.name.clone(),
            base_url: None,
            env_key: None,
            default_model: trace.run.provider_info.default_model.clone(),
        };
        let profile = resolve_provider_behavior_profile(Some(&info), &trace.run.model);
        let mut predecessor = baseline.clone();
        predecessor.tools.retain(|tool| tool.name != "update_plan");
        predecessor
            .system
            .retain(|part| part.name != "collaboration-mode");
        let names = predecessor
            .tools
            .iter()
            .map(|tool| tool.name.clone())
            .collect::<BTreeSet<_>>();
        let mut migrated = predecessor.clone();
        migrate_baseline_default_planning_surface(
            &mut migrated,
            &profile,
            "main",
            Some(&names),
            "fixture",
        )
        .unwrap();
        assert_eq!(
            runtime_codec::encode_value(&migrated).unwrap(),
            runtime_codec::encode_value(&baseline).unwrap()
        );
        for variant in 0..8 {
            let mut request = predecessor.clone();
            let mut direct = names.clone();
            let mut role = "main";
            let mut include_names = true;
            match variant {
                0 => role = "unknown-role",
                1 => include_names = false,
                2 => role = "child",
                3 => request.system.push(
                    runtime_codec::decode_value(&fixed_default_collaboration_raw_part()).unwrap(),
                ),
                4 => request.tools.push(
                    runtime_codec::decode_value(&fixed_default_update_plan_raw_spec()).unwrap(),
                ),
                5 => request.system.push(
                    request
                        .system
                        .iter()
                        .find(|part| part.name == "permissions")
                        .unwrap()
                        .clone(),
                ),
                6 => {
                    direct.insert("unrecorded-direct-tool".into());
                }
                7 => request.tools.push(request.tools[0].clone()),
                _ => unreachable!(),
            }
            let before = runtime_codec::encode_value(&request).unwrap();
            let result = migrate_baseline_default_planning_surface(
                &mut request,
                &profile,
                role,
                include_names.then_some(&direct),
                "forged fixture",
            );
            assert!(result.is_err(), "variant {variant} must fail closed");
            assert_eq!(
                runtime_codec::encode_value(&request).unwrap(),
                before,
                "failed migration is atomic"
            );
        }
    }

    #[tokio::test]
    async fn current_default_planning_specs_states_and_metadata_reject_forgery() {
        let manifest = load_checked_in_manifest().unwrap();
        for profile in [
            EvalProfile::Anthropic,
            EvalProfile::Openai,
            EvalProfile::Generic,
        ] {
            let surfaced =
                fixed_ts_contract_trace("provider-direct-model-only-exposure", profile).unwrap();
            assert_eq!(surfaced.model_requests.len(), 4);
            for (index, value) in surfaced.model_requests.iter().enumerate() {
                let request: ModelRequest = runtime_codec::decode_value(value).unwrap();
                let mut expected = vec![
                    rs("direct_model_probe"),
                    rs("tool_search"),
                    rs("update_plan"),
                ];
                if index >= 2 {
                    expected.push(rs("deferred_probe"));
                }
                assert_eq!(
                    request
                        .tools
                        .iter()
                        .map(|tool| tool.name.clone())
                        .collect::<Vec<_>>(),
                    expected
                );
            }
            validate_provider_behavior_trace_contract(
                &manifest,
                surfaced,
                TraceContractMode::Scripted,
            )
            .await
            .unwrap();
        }
        let trace = fixed_ts_contract_trace("read-summarize", EvalProfile::Anthropic)
            .unwrap()
            .clone();
        validate_provider_behavior_trace_contract(&manifest, &trace, TraceContractMode::Scripted)
            .await
            .unwrap();
        for variant in 0..16 {
            let mut forged = trace.clone();
            let request = &mut forged.model_requests[0];
            let progress = request["tools"]
                .as_array()
                .unwrap()
                .iter()
                .position(|tool| runtime_json_field_eq(tool, "name", "update_plan"))
                .unwrap();
            let mode = request["system"]
                .as_array()
                .unwrap()
                .iter()
                .position(|part| runtime_json_field_eq(part, "name", "collaboration-mode"))
                .unwrap();
            match variant {
                0 => {
                    *request["tools"][progress].get_mut("description").unwrap() =
                        "shortened contract".into()
                }
                1 => {
                    *request["tools"][progress]
                        .pointer_mut("/inputSchema/properties/plan/items/properties/status/enum")
                        .unwrap() = exact_json!(["pending", "completed"])
                }
                2 => {
                    request["tools"][progress]
                        .as_object_mut()
                        .unwrap()
                        .insert("unexpected", true.into());
                }
                3 => {
                    let duplicate = request["tools"][progress].clone();
                    request["tools"].as_array_mut().unwrap().push(duplicate);
                }
                4 => {
                    request["tools"].as_array_mut().unwrap().remove(progress);
                }
                5 => {
                    request["tools"].as_array_mut().unwrap().swap(progress, 0);
                }
                6 => {
                    *request["system"][mode].get_mut("text").unwrap() =
                        "<collaboration_mode>Plan</collaboration_mode>".into()
                }
                7 => *request["system"][mode].get_mut("cacheable").unwrap() = true.into(),
                8 => {
                    request["system"][mode]
                        .as_object_mut()
                        .unwrap()
                        .insert("cacheScope", "global".into());
                }
                9 => {
                    request["system"][mode]
                        .as_object_mut()
                        .unwrap()
                        .insert("unexpected", true.into());
                }
                10 => {
                    request["system"].as_array_mut().unwrap().remove(mode);
                }
                11 => {
                    let duplicate = request["system"][mode].clone();
                    request["system"].as_array_mut().unwrap().push(duplicate);
                }
                12 => {
                    request["system"].as_array_mut().unwrap().swap(mode, 0);
                }
                13 => {
                    *request["system"][mode].get_mut("name").unwrap() = "unknown-mode-part".into()
                }
                14 => {
                    *request["tools"][progress].get_mut("name").unwrap() =
                        "unrecorded-planning-tool".into()
                }
                15 => {
                    request["tools"][progress]
                        .pointer_mut("/inputSchema/properties")
                        .unwrap()
                        .as_object_mut()
                        .unwrap()
                        .insert("unrecordedField", exact_json!({"type":"string"}));
                }
                _ => unreachable!(),
            }
            validate_provider_behavior_trace_contract(
                &manifest,
                &forged,
                TraceContractMode::Scripted,
            )
            .await
            .expect_err("changed planning descriptor, state and metadata must remain untrusted");
        }
        let traces = FIXED_TS_CONTRACT_TRACES.as_ref().unwrap();
        let (child_trace, child_index) = traces
            .values()
            .find_map(|trace| {
                trace
                    .model_requests
                    .iter()
                    .enumerate()
                    .find_map(|(index, value)| {
                        let request: ModelRequest = runtime_codec::decode_value(value).unwrap();
                        request_history_prefix_len(&request, &trace.history)
                            .unwrap()
                            .is_none()
                            .then_some((trace, index))
                    })
            })
            .expect("the fixed corpus retains real child request states");
        validate_provider_behavior_trace_contract(
            &manifest,
            child_trace,
            TraceContractMode::Scripted,
        )
        .await
        .unwrap();
        let mut forged_child = child_trace.clone();
        forged_child.model_requests[child_index]["tools"]
            .as_array_mut()
            .unwrap()
            .push(fixed_default_update_plan_raw_spec());
        validate_provider_behavior_trace_contract(
            &manifest,
            &forged_child,
            TraceContractMode::Scripted,
        )
        .await
        .expect_err("root progress authority must not enter a child tool state");
    }

    fn runtime_files<const N: usize>(
        entries: [(&str, &str); N],
    ) -> BTreeMap<RuntimeString, RuntimeString> {
        entries
            .into_iter()
            .map(|(path, content)| (rs(path), rs(content)))
            .collect()
    }

    fn runtime_string_set<const N: usize>(values: [&str; N]) -> BTreeSet<RuntimeString> {
        values.into_iter().map(rs).collect()
    }

    #[test]
    fn provider_behavior_unit_runtime_codecs_cover_the_complete_family() {
        macro_rules! assert_runtime_encode_contract {
            ($type:ty; $( $variant:path => $tag:literal ),+ $(,)?) => {{
                let cases: &[($type, &str)] = &[$(($variant, $tag)),+];
                for (value, tag) in cases {
                    let runtime_text = crate::runtime_values::runtime_codec::encode_text(value)
                        .expect("runtime unit enum encode");
                    assert_eq!(
                        runtime_text,
                        crate::runtime_values::RuntimeString::from(format!("\"{tag}\""))
                    );
                }
            }};
        }

        macro_rules! assert_runtime_decode_contract {
            ($type:ty; $( $variant:path => $tag:literal ),+ $(,)?) => {{
                let cases: &[($type, &str)] = &[$(($variant, $tag)),+];
                for (value, tag) in cases {
                    assert_eq!(
                        crate::runtime_values::runtime_codec::decode_text::<$type>(
                            &crate::runtime_values::RuntimeString::from(format!("\"{tag}\"")),
                        )
                        .expect("runtime unit enum decode"),
                        *value,
                    );
                }

                let unknown = crate::runtime_values::runtime_codec::decode_text::<$type>(
                    &crate::runtime_values::RuntimeString::from(
                        "\"__runtime_unknown_variant__\"",
                    ),
                )
                .unwrap_err();
                assert_eq!(
                    unknown.kind(),
                    &crate::runtime_values::RuntimeCodecErrorKind::UnknownEnumVariant,
                );
                assert_eq!(
                    unknown.pointer(),
                    crate::runtime_values::RuntimeString::default(),
                );

                for wrong_shape in [
                    crate::runtime_values::RuntimeJson::Null,
                    crate::runtime_values::RuntimeJson::Bool(true),
                ] {
                    let error = crate::runtime_values::runtime_codec::decode_value::<$type>(
                        &wrong_shape,
                    )
                    .unwrap_err();
                    assert_eq!(
                        error.kind(),
                        &crate::runtime_values::RuntimeCodecErrorKind::InvalidEnumShape,
                    );
                    assert_eq!(
                        error.pointer(),
                        crate::runtime_values::RuntimeString::default(),
                    );
                }

                let first_tag = cases[0].1;
                let mut payload = crate::runtime_values::RuntimeObject::new();
                payload.insert(first_tag, crate::runtime_values::RuntimeJson::Null);
                let payload = crate::runtime_values::runtime_codec::decode_value::<$type>(
                    &crate::runtime_values::RuntimeJson::Object(payload),
                )
                .unwrap_err();
                assert_eq!(
                    payload.kind(),
                    &crate::runtime_values::RuntimeCodecErrorKind::InvalidEnumShape,
                );
                assert_eq!(
                    payload.pointer(),
                    crate::runtime_values::RuntimeString::from(format!("/{first_tag}")),
                );

                let mut unknown_payload = crate::runtime_values::RuntimeObject::new();
                unknown_payload.insert(
                    "__runtime_unknown_variant__",
                    crate::runtime_values::RuntimeJson::Null,
                );
                let unknown_payload =
                    crate::runtime_values::runtime_codec::decode_value::<$type>(
                        &crate::runtime_values::RuntimeJson::Object(unknown_payload),
                    )
                    .unwrap_err();
                assert_eq!(
                    unknown_payload.kind(),
                    &crate::runtime_values::RuntimeCodecErrorKind::UnknownEnumVariant,
                );
                assert_eq!(
                    unknown_payload.pointer(),
                    crate::runtime_values::RuntimeString::from(
                        "/__runtime_unknown_variant__",
                    ),
                );

                let surrogate = crate::runtime_values::RuntimeString::from_utf16([
                    b'"' as u16,
                    0xd800,
                    b'"' as u16,
                ]);
                let surrogate = crate::runtime_values::runtime_codec::decode_text::<$type>(
                    &surrogate,
                )
                .unwrap_err();
                assert_eq!(
                    surrogate.kind(),
                    &crate::runtime_values::RuntimeCodecErrorKind::UnknownEnumVariant,
                );
                assert_eq!(
                    surrogate.pointer(),
                    crate::runtime_values::RuntimeString::default(),
                );
            }};
        }

        macro_rules! assert_runtime_unit_enum_contract {
            ($type:ty; $( $variant:path => $tag:literal ),+ $(,)?) => {{
                assert_runtime_encode_contract!($type; $( $variant => $tag ),+);
                assert_runtime_decode_contract!($type; $( $variant => $tag ),+);
            }};
        }

        macro_rules! assert_serde_decode {
            ($type:ty; $( $variant:path => $tag:literal ),+ $(,)?) => {{
                let cases: &[($type, &str)] = &[$(($variant, $tag)),+];
                for (expected, tag) in cases {
                    assert_eq!(
                        serde_json::from_str::<$type>(&format!("\"{tag}\"")).unwrap(),
                        *expected,
                    );
                }

                assert!(serde_json::from_str::<$type>(
                    "\"__runtime_unknown_variant__\"",
                )
                .is_err());
                assert!(serde_json::from_str::<$type>("null").is_err());
                assert!(serde_json::from_str::<$type>("true").is_err());

                let first_tag = cases[0].1;
                assert_eq!(
                    serde_json::from_str::<$type>(&format!(r#"{{"{first_tag}":null}}"#))
                        .unwrap(),
                    cases[0].0,
                    "serde accepts a payload-shaped unit tag while runtime rejects it",
                );
                assert!(serde_json::from_str::<$type>(
                    r#"{"__runtime_unknown_variant__":null}"#,
                )
                .is_err());
                assert!(serde_json::from_str::<$type>(r#""\ud800""#).is_err());
            }};
        }

        macro_rules! assert_serde_both {
            ($type:ty; $( $variant:path => $tag:literal ),+ $(,)?) => {{
                let cases: &[($type, &str)] = &[$(($variant, $tag)),+];
                for (value, tag) in cases {
                    assert_eq!(serde_json::to_string(value).unwrap(), format!("\"{tag}\""));
                }
                assert_serde_decode!($type; $( $variant => $tag ),+);
            }};
        }

        assert_serde_both!(EvalPermissionMode;
            EvalPermissionMode::BypassPermissions => "bypassPermissions",
            EvalPermissionMode::Default => "default",
        );
        assert_runtime_unit_enum_contract!(EvalPermissionMode;
            EvalPermissionMode::BypassPermissions => "bypassPermissions",
            EvalPermissionMode::Default => "default",
        );

        assert_serde_both!(EvalToolFixture;
            EvalToolFixture::BuiltinWrite => "builtin_write",
            EvalToolFixture::BuiltinToolSearch => "builtin_tool_search",
            EvalToolFixture::SelfDeny => "self_deny",
            EvalToolFixture::SubagentReportWrite => "subagent_report_write",
            EvalToolFixture::ListPeersProbe => "list_peers_probe",
            EvalToolFixture::SendMessageProbe => "send_message_probe",
            EvalToolFixture::ExecCommandProbe => "exec_command_probe",
            EvalToolFixture::WriteStdinProbe => "write_stdin_probe",
            EvalToolFixture::BackgroundNoticeProbe => "background_notice_probe",
            EvalToolFixture::SpillProbe => "spill_probe",
            EvalToolFixture::DirectModelProbe => "direct_model_probe",
            EvalToolFixture::DeferredProbe => "deferred_probe",
        );
        assert_runtime_unit_enum_contract!(EvalToolFixture;
            EvalToolFixture::BuiltinWrite => "builtin_write",
            EvalToolFixture::BuiltinToolSearch => "builtin_tool_search",
            EvalToolFixture::SelfDeny => "self_deny",
            EvalToolFixture::SubagentReportWrite => "subagent_report_write",
            EvalToolFixture::ListPeersProbe => "list_peers_probe",
            EvalToolFixture::SendMessageProbe => "send_message_probe",
            EvalToolFixture::ExecCommandProbe => "exec_command_probe",
            EvalToolFixture::WriteStdinProbe => "write_stdin_probe",
            EvalToolFixture::BackgroundNoticeProbe => "background_notice_probe",
            EvalToolFixture::SpillProbe => "spill_probe",
            EvalToolFixture::DirectModelProbe => "direct_model_probe",
            EvalToolFixture::DeferredProbe => "deferred_probe",
        );

        assert_serde_both!(EvalProfile;
            EvalProfile::Anthropic => "anthropic",
            EvalProfile::Openai => "openai",
            EvalProfile::Generic => "generic",
            EvalProfile::Qwen => "qwen",
        );
        assert_runtime_unit_enum_contract!(EvalProfile;
            EvalProfile::Anthropic => "anthropic",
            EvalProfile::Openai => "openai",
            EvalProfile::Generic => "generic",
            EvalProfile::Qwen => "qwen",
        );

        assert_serde_decode!(ScriptedSessionRole;
            ScriptedSessionRole::Main => "main",
            ScriptedSessionRole::Child => "child",
        );
        assert_runtime_decode_contract!(ScriptedSessionRole;
            ScriptedSessionRole::Main => "main",
            ScriptedSessionRole::Child => "child",
        );

        assert_serde_both!(TraceContractMode;
            TraceContractMode::Scripted => "scripted",
            TraceContractMode::Live => "live",
        );
        assert_runtime_unit_enum_contract!(TraceContractMode;
            TraceContractMode::Scripted => "scripted",
            TraceContractMode::Live => "live",
        );

        for (value, text) in [
            (ChildSeedKind::Fresh, "\"fresh\""),
            (ChildSeedKind::Fork, "\"fork\""),
        ] {
            assert_eq!(serde_json::to_string(&value).unwrap(), text);
        }
        assert_runtime_encode_contract!(ChildSeedKind;
            ChildSeedKind::Fresh => "fresh",
            ChildSeedKind::Fork => "fork",
        );
    }

    #[test]
    fn fixed_ts_contract_trace_jsonl_preserves_surrogate_and_literal_marker_strings() {
        let fixture =
            include_str!("../../tests/fixtures/provider_behavior/v1/baseline.contract.jsonl");
        let mut row = first_baseline_contract_row(fixture);
        let surrogate = runtime_json::parse(&rs(r#""\ud800""#)).unwrap();
        let literal_marker = runtime_json::parse(&rs(r#""\ufdd0ud800""#)).unwrap();
        assert_ne!(surrogate, literal_marker);
        row["trace"]["modelRequests"][0]["surrogate"] = surrogate.clone();
        row["trace"]["modelRequests"][0]["literalMarker"] = literal_marker.clone();

        let encoded_wrapper = runtime_json::stringify(&row);
        assert!(encoded_wrapper.contains(r#""surrogate":"\ud800""#));
        assert!(encoded_wrapper.contains("\"literalMarker\":\"\u{fdd0}ud800\""));
        let reparsed = runtime_json::parse(&encoded_wrapper).unwrap();
        let parsed = parse_baseline_contract_row(&reparsed, 1).unwrap();
        assert_eq!(parsed.trace.model_requests[0]["surrogate"], surrogate);
        assert_eq!(
            parsed.trace.model_requests[0]["literalMarker"],
            literal_marker
        );

        let trace_line = parsed.trace.to_json_line().unwrap();
        assert!(trace_line.contains(r#""surrogate":"\ud800""#));
        assert!(trace_line.contains("\"literalMarker\":\"\u{fdd0}ud800\""));
        assert_eq!(
            ProviderBehaviorTrace::from_json_line(&trace_line).unwrap(),
            parsed.trace
        );
    }

