    /// Whether the shared config-env lock becomes free within a bounded wait.
    ///
    /// Two things a bare `try_lock().is_ok()` gets wrong. The test binary runs cases in
    /// parallel, so another case's guard may hold the same lock at that instant and the
    /// assertion fails for a reason that has nothing to do with this guard; other holders
    /// keep it for milliseconds, so a bounded wait tells that apart from a guard that
    /// leaked it. And a `Mutex<()>` that any other case panicked while holding stays
    /// POISONED for the rest of the run, so `is_ok()` is false forever after an unrelated
    /// failure — poisoning carries no meaning for a unit-typed lock, which is why every
    /// other holder in this crate takes it with `unwrap_or_else(|e| e.into_inner())`.
    fn shared_config_lock_becomes_free() -> bool {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            match crate::test_support::CONFIG_ENV_LOCK.try_lock() {
                Ok(_) | Err(std::sync::TryLockError::Poisoned(_)) => return true,
                Err(std::sync::TryLockError::WouldBlock) => {}
            }
            if std::time::Instant::now() >= deadline {
                return false;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    #[test]
    fn eval_environment_holds_the_shared_config_env_lock() {
        let workspace = EvalWorkspace::create("shared-config-lock").unwrap();
        let environment = EvalEnvironment::install(workspace.path()).unwrap();

        assert!(crate::test_support::CONFIG_ENV_LOCK.try_lock().is_err());
        drop(environment);
        assert!(shared_config_lock_becomes_free());
    }

    #[test]
    fn file_freshness_requires_lifecycle_proven_happens_before() {
        let causal = [FileStateInterval {
            start_event_index: 1,
            terminal_event_index: 2,
        }];
        assert_eq!(
            reconstructed_freshness_before(Some(&causal), &[], None, 3),
            ReconstructedFreshness::Proven
        );
        let later = [FileStateInterval {
            start_event_index: 3,
            terminal_event_index: 4,
        }];
        assert_eq!(
            reconstructed_freshness_before(Some(&later), &[], None, 3),
            ReconstructedFreshness::Unread
        );
        let overlap = [FileStateInterval {
            start_event_index: 2,
            terminal_event_index: 4,
        }];
        assert_eq!(
            reconstructed_freshness_before(Some(&overlap), &[], None, 3),
            ReconstructedFreshness::Uncertain
        );
        let opaque_after_read = [FileStateInterval {
            start_event_index: 2,
            terminal_event_index: 3,
        }];
        assert_eq!(
            reconstructed_freshness_before(Some(&causal), &opaque_after_read, None, 4),
            ReconstructedFreshness::Uncertain
        );
        let read_after_opaque = [FileStateInterval {
            start_event_index: 4,
            terminal_event_index: 5,
        }];
        assert_eq!(
            reconstructed_freshness_before(Some(&read_after_opaque), &opaque_after_read, None, 6,),
            ReconstructedFreshness::Proven
        );
    }

    #[test]
    fn absent_file_existence_rejects_only_causally_unresolved_invalidators() {
        let completed_path_delete = [FileStateInterval {
            start_event_index: 1,
            terminal_event_index: 2,
        }];
        assert!(!reconstructed_absence_is_uncertain(
            &[],
            Some(&completed_path_delete),
            3,
        ));

        let overlapping_path_delete = [FileStateInterval {
            start_event_index: 1,
            terminal_event_index: 3,
        }];
        assert!(reconstructed_absence_is_uncertain(
            &[],
            Some(&overlapping_path_delete),
            3,
        ));

        let later_path_delete = [FileStateInterval {
            start_event_index: 3,
            terminal_event_index: 4,
        }];
        assert!(!reconstructed_absence_is_uncertain(
            &[],
            Some(&later_path_delete),
            3,
        ));

        let completed_opaque_tool = [FileStateInterval {
            start_event_index: 1,
            terminal_event_index: 2,
        }];
        assert!(reconstructed_absence_is_uncertain(
            &completed_opaque_tool,
            None,
            3,
        ));
    }

