    fn add_live_tool_event_turn_ids(trace: &mut ProviderBehaviorTrace) {
        let turn_id = trace
            .engine_events
            .iter()
            .find(|event| runtime_json_field_eq(event, "type", "turn.started"))
            .and_then(|event| event.get("turnId"))
            .cloned()
            .expect("raw Query trace must contain an identified turn");
        for event in &mut trace.engine_events {
            if runtime_json_field_eq(event, "type", "tool.event") {
                event
                    .as_object_mut()
                    .unwrap()
                    .insert("turnId".to_owned(), turn_id.clone());
                // Appending puts `turnId` at the object tail; the round-trip
                // validator compares against the codec's canonical field
                // order, so re-encode the patched event through the codec.
                *event = runtime_codec::encode_value(
                    &runtime_codec::decode_value::<EngineEvent>(event)
                        .expect("patched live tool.event stays decodable"),
                )
                .expect("canonical tool.event re-encode");
            }
        }
    }

