    #[tokio::test]
    async fn patch_replay_canonicalizes_alias_io_but_preserves_raw_results() {
        let operations = parse_patch(&rs(
            "*** Begin Patch\n*** Update File: ./update.txt\n@@\n-old update\n+new update\n*** Delete File: ./delete.txt\n*** Add File: dir/../add.txt\n+added\n*** Update File: ./move.txt\n*** Move to: nested/../moved.txt\n@@\n-old move\n+new move\n*** End Patch",
        ))
        .unwrap();
        validate_patch_replay_paths(&operations).unwrap();
        let io = ReplayPatchIo {
            files: Mutex::new(runtime_files([
                ("update.txt", "old update\n"),
                ("delete.txt", "delete me\n"),
                ("move.txt", "old move\n"),
            ])),
            touched_paths: Mutex::new(BTreeSet::new()),
        };

        let results = apply_patch_ops(&operations, &io).await.unwrap();
        assert_eq!(
            results
                .iter()
                .map(|result| (result.path.clone(), result.move_path.clone()))
                .collect::<Vec<_>>(),
            vec![
                (rs("./update.txt"), None),
                (rs("./delete.txt"), None),
                (rs("dir/../add.txt"), None),
                (rs("./move.txt"), Some(rs("nested/../moved.txt"))),
            ]
        );
        assert_eq!(
            io.files.into_inner().unwrap(),
            runtime_files([
                ("add.txt", "added\n"),
                ("moved.txt", "new move\n"),
                ("update.txt", "new update\n"),
            ])
        );
        assert_eq!(
            io.touched_paths.into_inner().unwrap(),
            runtime_string_set([
                "add.txt",
                "delete.txt",
                "move.txt",
                "moved.txt",
                "update.txt"
            ])
        );
        assert_eq!(
            reconstructed_patch_file_events(&results).unwrap(),
            vec![
                exact_json!({"path":"$WORKSPACE/update.txt","kind":"modify"}),
                exact_json!({"path":"$WORKSPACE/delete.txt","kind":"delete"}),
                exact_json!({"path":"$WORKSPACE/add.txt","kind":"create"}),
                exact_json!({"path":"$WORKSPACE/move.txt","kind":"delete"}),
                exact_json!({"path":"$WORKSPACE/moved.txt","kind":"create"}),
            ]
        );
    }

    #[tokio::test]
    async fn patch_replay_preserves_sequential_same_alias_and_same_move_operands() {
        let cases = [
            (
                "*** Begin Patch\n*** Update File: state.txt\n@@\n-one\n+two\n*** Update File: state.txt\n@@\n-two\n+three\n*** End Patch",
                vec![(rs("state.txt"), None), (rs("state.txt"), None)],
                rs("three\n"),
                vec![
                    exact_json!({"path":"$WORKSPACE/state.txt","kind":"modify"}),
                    exact_json!({"path":"$WORKSPACE/state.txt","kind":"modify"}),
                ],
            ),
            (
                "*** Begin Patch\n*** Update File: state.txt\n@@\n-one\n+two\n*** Update File: dir/../state.txt\n@@\n-two\n+three\n*** End Patch",
                vec![(rs("state.txt"), None), (rs("dir/../state.txt"), None)],
                rs("three\n"),
                vec![
                    exact_json!({"path":"$WORKSPACE/state.txt","kind":"modify"}),
                    exact_json!({"path":"$WORKSPACE/state.txt","kind":"modify"}),
                ],
            ),
            (
                "*** Begin Patch\n*** Update File: ./state.txt\n*** Move to: ./state.txt\n@@\n-one\n+two\n*** End Patch",
                vec![(rs("./state.txt"), None)],
                rs("two\n"),
                vec![exact_json!({"path":"$WORKSPACE/state.txt","kind":"modify"})],
            ),
        ];

        for (patch, expected_results, expected_content, expected_events) in cases {
            let operations = parse_patch(&rs(patch)).unwrap();
            validate_patch_replay_paths(&operations).unwrap();
            let io = ReplayPatchIo {
                files: Mutex::new(runtime_files([("state.txt", "one\n")])),
                touched_paths: Mutex::new(BTreeSet::new()),
            };
            let results = apply_patch_ops(&operations, &io).await.unwrap();
            assert_eq!(
                results
                    .iter()
                    .map(|result| (result.path.clone(), result.move_path.clone()))
                    .collect::<Vec<_>>(),
                expected_results
            );
            assert_eq!(
                io.files.into_inner().unwrap(),
                BTreeMap::from([(rs("state.txt"), expected_content)])
            );
            assert_eq!(
                reconstructed_patch_file_events(&results).unwrap(),
                expected_events
            );
        }
    }

    #[test]
    fn restored_file_keeps_producer_events_without_a_net_file_change_side_effect() {
        let before = runtime_files([("state.txt", "original\n")]);
        let after = before.clone();
        let events = vec![
            exact_json!({
                "type":"item.started",
                "item":{"type":"tool_call","id":"e1","toolName":"edit","arguments":{},"status":"in_progress"}
            }),
            exact_json!({
                "type":"tool.event","toolUseId":"e1",
                "event":{"type":"file_change","change":{"path":"$WORKSPACE/state.txt","kind":"modify"}}
            }),
            exact_json!({
                "type":"item.completed",
                "item":{"type":"tool_call","id":"e1","toolName":"edit","arguments":{},"status":"completed","result":{}}
            }),
            exact_json!({
                "type":"item.started",
                "item":{"type":"tool_call","id":"e2","toolName":"edit","arguments":{},"status":"in_progress"}
            }),
            exact_json!({
                "type":"tool.event","toolUseId":"e2",
                "event":{"type":"file_change","change":{"path":"$WORKSPACE/state.txt","kind":"modify"}}
            }),
            exact_json!({
                "type":"item.completed",
                "item":{"type":"tool_call","id":"e2","toolName":"edit","arguments":{},"status":"completed","result":{}}
            }),
        ];

        let effects = derive_side_effects(&events, &before, &after).unwrap();
        assert_eq!(
            effects
                .iter()
                .filter(|effect| runtime_json_field_eq(effect, "type", "tool_call"))
                .count(),
            2
        );
        assert!(effects
            .iter()
            .all(|effect| !runtime_json_field_eq(effect, "type", "file_change")));
    }

