    #[test]
    fn live_prestart_partition_is_not_misclassified_as_a_parallel_batch() {
        let reordered = || {
            vec![
                tool_event("item.started", "r2"),
                tool_event("item.started", "r1"),
                tool_event("item.completed", "r2"),
                tool_event("item.completed", "r1"),
            ]
        };

        let mut strict = reordered();
        assert!(
            normalize_parallel_terminal_events(&parallel_history(), &mut strict)
                .unwrap_err()
                .to_string()
                .contains("do not follow model order")
        );

        let mut live = reordered();
        let prestartable = runtime_string_set(["r2"]);
        let batches = normalize_parallel_terminal_events_with_prestarts(
            &parallel_history(),
            &mut live,
            Some(&prestartable),
        )
        .unwrap();
        assert!(batches.is_empty());

        let mut two_read_only_calls_cannot_reverse = reordered();
        let both_prestartable = runtime_string_set(["r1", "r2"]);
        assert!(normalize_parallel_terminal_events_with_prestarts(
            &parallel_history(),
            &mut two_read_only_calls_cannot_reverse,
            Some(&both_prestartable),
        )
        .unwrap_err()
        .to_string()
        .contains("live prestart partition"));

        let mut non_contiguous_reorder = vec![
            tool_event("item.started", "r2"),
            exact_json!({"type":"item.completed","item":{"type":"agent_message","id":"a1","text":"gap"}}),
            tool_event("item.started", "r1"),
            tool_event("item.completed", "r2"),
            tool_event("item.completed", "r1"),
        ];
        assert!(normalize_parallel_terminal_events(
            &parallel_history(),
            &mut non_contiguous_reorder,
        )
        .unwrap_err()
        .to_string()
        .contains("do not follow model order"));
    }

    #[test]
    fn normalized_call_bijection_rejects_missing_duplicate_and_mismatched_starts() {
        let calls = vec![exact_json!({
            "id":"r1",
            "visibleName":"read",
            "visibleInput":{"path":"a.txt"},
            "toolKind":"function",
            "inputFormat":"json",
            "internalName":"read",
            "internalInput":{"path":"a.txt"}
        })];
        let effects = vec![exact_json!({
            "type":"tool_call",
            "id":"r1",
            "name":"read",
            "input":{"path":"a.txt"},
            "status":"completed",
            "result":{"ok":true}
        })];
        let started = exact_json!({
            "type":"item.started",
            "item":{
                "type":"tool_call",
                "id":"r1",
                "toolName":"read",
                "arguments":{"path":"a.txt"},
                "status":"in_progress"
            }
        });
        assert!(validate_normalized_call_bijection(
            &calls,
            &effects,
            std::slice::from_ref(&started),
        )
        .is_ok());
        assert!(validate_normalized_call_bijection(&calls, &effects, &[])
            .unwrap_err()
            .to_string()
            .contains("one item.started"));
        assert!(
            validate_normalized_call_bijection(&calls, &effects, &[started.clone(), started])
                .unwrap_err()
                .to_string()
                .contains("duplicate item.started")
        );
        let mismatched = exact_json!({
            "type":"item.started",
            "item":{
                "type":"tool_call",
                "id":"r1",
                "toolName":"write",
                "arguments":{"path":"a.txt"},
                "status":"in_progress"
            }
        });
        assert!(
            validate_normalized_call_bijection(&calls, &effects, &[mismatched])
                .unwrap_err()
                .to_string()
                .contains("runtime item.started identity/input")
        );
    }

