    fn parallel_uuid_fixture() -> (ProviderBehaviorTrace, Vec<ParallelBatch>) {
        let trace = fixed_ts_contract_trace("provider-parallel-subagents", EvalProfile::Anthropic)
            .unwrap()
            .clone();
        let mut events = trace.engine_events.clone();
        let batches = normalize_parallel_terminal_events(&trace.history, &mut events).unwrap();
        (trace, batches)
    }

    fn replace_parallel_uuid_tokens_with<F>(
        trace: &mut ProviderBehaviorTrace,
        batches: &[ParallelBatch],
        raw_uuid_for: F,
    ) where
        F: Fn(&RuntimeString) -> RuntimeString,
    {
        for id in batches.iter().flat_map(|batch| &batch.ids) {
            let token = RuntimeString::from_utf8("$PARALLEL_TOOL_RESULT_UUID:").concat(id);
            let raw_uuid = raw_uuid_for(id);
            for message in &mut trace.history {
                if runtime_json_field_eq(message, "type", "tool_result")
                    && message.get("toolUseId").and_then(Json::as_str) == Some(id)
                    && message.get("uuid").and_then(Json::as_str) == Some(&token)
                {
                    message["uuid"] = Json::String(raw_uuid.clone());
                }
            }
            for request in &mut trace.model_requests {
                for message in request["messages"].as_array_mut().unwrap() {
                    if runtime_json_field_eq(message, "type", "tool_result")
                        && message.get("toolUseId").and_then(Json::as_str) == Some(id)
                        && message.get("uuid").and_then(Json::as_str) == Some(&token)
                    {
                        message["uuid"] = Json::String(raw_uuid.clone());
                    }
                }
            }
        }
    }

    #[test]
    fn parallel_uuid_audit_covers_the_whole_trace_and_exact_token_values() {
        let token = "$PARALLEL_TOOL_RESULT_UUID:r1";
        let audit = ParallelUuidNormalization {
            pointers: vec![rs("/history/0/uuid")],
            expected_tokens: BTreeMap::from([("/history/0/uuid".to_owned(), rs(token))]),
            raw_uuids: runtime_string_set(["raw-result-uuid"]),
        };
        let trace = exact_json!({
            "history":[{"uuid":(rs(token))}],
            "normalization":{
                "nonContractParallelUuidPointers":["/history/0/uuid"]
            }
        });
        validate_parallel_uuid_whole_trace(&trace, &audit).unwrap();

        let mut raw_residual = trace.clone();
        raw_residual["finalText"] = Json::String(rs("raw-result-uuid"));
        assert!(validate_parallel_uuid_whole_trace(&raw_residual, &audit)
            .unwrap_err()
            .to_string()
            .contains("raw uuid remains"));

        let mut embedded = trace.clone();
        embedded["history"][0]["uuid"] =
            Json::String(RuntimeString::from(format!("prefix {token}")));
        assert!(validate_parallel_uuid_whole_trace(&embedded, &audit)
            .unwrap_err()
            .to_string()
            .contains("must equal its approved token"));

        let mut undeclared = trace.clone();
        undeclared["sideEffects"] = exact_json!([{"uuid":(rs(token))}]);
        assert!(validate_parallel_uuid_whole_trace(&undeclared, &audit)
            .unwrap_err()
            .to_string()
            .contains("undeclared parallel uuid token"));

        let mut keyed_object = RuntimeObject::new();
        keyed_object.insert(rs(token), Json::String(rs("value")));
        keyed_object.insert("history", exact_json!([{"uuid":(rs(token))}]));
        keyed_object.insert(
            "normalization",
            exact_json!({"nonContractParallelUuidPointers":["/history/0/uuid"]}),
        );
        let keyed = Json::Object(keyed_object);
        assert!(validate_parallel_uuid_whole_trace(&keyed, &audit)
            .unwrap_err()
            .to_string()
            .contains("object key"));
    }

    #[test]
    fn parallel_uuid_contract_accepts_two_causal_later_main_request_copies() {
        let mut trace =
            fixed_ts_contract_trace("provider-parallel-subagents", EvalProfile::Anthropic)
                .unwrap()
                .clone();
        let source_index = trace
            .model_requests
            .iter()
            .rposition(|request| {
                runtime_json_field_eq(request, "cacheKey", EVAL_MAIN_SESSION_ID)
                    && request
                        .get("messages")
                        .and_then(Json::as_array)
                        .is_some_and(|messages| {
                            messages.iter().any(|message| {
                                runtime_json_field_eq(message, "type", "tool_result")
                                    && message.get("uuid").and_then(Json::as_str).is_some_and(
                                        |uuid| uuid.starts_with("$PARALLEL_TOOL_RESULT_UUID:"),
                                    )
                            })
                        })
            })
            .unwrap();
        let retry_index = trace.model_requests.len();
        let retry = trace.model_requests[source_index].clone();
        for (message_index, message) in retry["messages"].as_array().unwrap().iter().enumerate() {
            if message
                .get("uuid")
                .and_then(Json::as_str)
                .is_some_and(|uuid| uuid.starts_with("$PARALLEL_TOOL_RESULT_UUID:"))
            {
                trace
                    .normalization
                    .non_contract_parallel_uuid_pointers
                    .push(RuntimeString::from(format!(
                        "/modelRequests/{retry_index}/messages/{message_index}/uuid"
                    )));
            }
        }
        trace
            .normalization
            .non_contract_parallel_uuid_pointers
            .sort();
        let source_prefix = RuntimeString::from(format!("/modelRequests/{source_index}/"));
        let retry_prefix = RuntimeString::from(format!("/modelRequests/{retry_index}/"));
        let retry_host_pointers = trace
            .normalization
            .non_contract_host_pointers
            .iter()
            .filter(|&pointer| runtime_starts_with(pointer, &source_prefix))
            .map(|pointer| retry_prefix.concat(&pointer.slice_utf16(source_prefix.len_utf16()..)))
            .collect::<Vec<_>>();
        trace
            .normalization
            .non_contract_host_pointers
            .extend(retry_host_pointers);
        trace.normalization.non_contract_host_pointers.sort();
        trace.model_requests.push(retry);

        let mut events = trace.engine_events.clone();
        let batches = normalize_parallel_terminal_events(&trace.history, &mut events).unwrap();
        validate_parallel_uuid_contract(&trace, &batches).unwrap();
    }

