    #[test]
    fn parallel_uuid_normalizer_accepts_full_and_recent_child_include_or_omit() {
        let mut trace =
            fixed_ts_contract_trace("provider-parallel-subagents", EvalProfile::Anthropic)
                .unwrap()
                .clone();
        let mut events = trace.engine_events.clone();
        let batches = normalize_parallel_terminal_events(&trace.history, &mut events).unwrap();
        replace_parallel_uuid_tokens_with(&mut trace, &batches, |id| {
            RuntimeString::from_utf8("raw-result-").concat(id)
        });

        let source_index = trace
            .model_requests
            .iter()
            .rposition(|request| {
                runtime_json_field_eq(request, "cacheKey", EVAL_MAIN_SESSION_ID)
                    && request
                        .get("messages")
                        .and_then(Json::as_array)
                        .is_some_and(|messages| {
                            messages.iter().any(|message| {
                                runtime_json_field_eq(message, "type", "tool_result")
                            })
                        })
            })
            .unwrap();

        let full_include_index = trace.model_requests.len();
        let mut full_include = trace.model_requests[source_index].clone();
        full_include["cacheKey"] = Json::String(rs("child-full-include"));
        trace.model_requests.push(full_include.clone());

        let full_omit_index = trace.model_requests.len();
        let mut full_omit = full_include.clone();
        full_omit["cacheKey"] = Json::String(rs("child-full-omit"));
        full_omit["messages"]
            .as_array_mut()
            .unwrap()
            .retain(|message| !runtime_json_field_eq(message, "type", "tool_result"));
        trace.model_requests.push(full_omit);

        let recent_include_index = trace.model_requests.len();
        let mut recent_include = trace.model_requests[source_index].clone();
        recent_include["cacheKey"] = Json::String(rs("child-recent-include"));
        recent_include["messages"] =
            Json::Array(vec![trace.history[1].clone(), trace.history[2].clone()]);
        trace.model_requests.push(recent_include);

        let recent_omit_index = trace.model_requests.len();
        let mut recent_omit = trace.model_requests[source_index].clone();
        recent_omit["cacheKey"] = Json::String(rs("child-recent-omit"));
        recent_omit["messages"] = Json::Array(vec![trace.history[0].clone()]);
        trace.model_requests.push(recent_omit);

        let normalization = normalize_parallel_tool_result_uuids(
            &batches,
            &mut trace.history,
            &mut trace.model_requests,
        )
        .unwrap();
        let expected_child_pointers = [
            RuntimeString::from(format!(
                "/modelRequests/{full_include_index}/messages/2/uuid"
            )),
            RuntimeString::from(format!(
                "/modelRequests/{full_include_index}/messages/3/uuid"
            )),
            RuntimeString::from(format!(
                "/modelRequests/{recent_include_index}/messages/1/uuid"
            )),
        ];
        assert_eq!(normalization.pointers.len(), 7);
        for pointer in expected_child_pointers {
            assert!(normalization.pointers.contains(&pointer), "{pointer:?}");
        }
        let full_omit_prefix = RuntimeString::from(format!("/modelRequests/{full_omit_index}/"));
        assert!(normalization
            .pointers
            .iter()
            .all(|pointer| !runtime_starts_with(pointer, &full_omit_prefix)));
        let recent_omit_prefix =
            RuntimeString::from(format!("/modelRequests/{recent_omit_index}/"));
        assert!(normalization
            .pointers
            .iter()
            .all(|pointer| !runtime_starts_with(pointer, &recent_omit_prefix)));

        trace.normalization.non_contract_parallel_uuid_pointers = normalization.pointers;
        validate_parallel_uuid_contract(&trace, &batches).unwrap();
    }

