    #[test]
    fn parallel_uuid_normalizer_rejects_duplicate_matching_history_tool_uses() {
        let mut trace =
            fixed_ts_contract_trace("provider-parallel-subagents", EvalProfile::Anthropic)
                .unwrap()
                .clone();
        let mut events = trace.engine_events.clone();
        let batches = normalize_parallel_terminal_events(&trace.history, &mut events).unwrap();
        let assistant = trace
            .history
            .iter_mut()
            .find(|message| {
                runtime_json_field_eq(message, "type", "assistant")
                    && message
                        .get("content")
                        .and_then(Json::as_array)
                        .is_some_and(|content| {
                            content
                                .iter()
                                .any(|block| runtime_json_field_eq(block, "id", "t1"))
                        })
            })
            .unwrap();
        let duplicate = assistant["content"]
            .as_array()
            .unwrap()
            .iter()
            .find(|block| runtime_json_field_eq(block, "id", "t1"))
            .unwrap()
            .clone();
        assistant["content"]
            .as_array_mut()
            .unwrap()
            .push(duplicate.clone());
        for request in &mut trace.model_requests {
            if !runtime_json_field_eq(request, "cacheKey", EVAL_MAIN_SESSION_ID) {
                continue;
            }
            if let Some(assistant) =
                request["messages"]
                    .as_array_mut()
                    .unwrap()
                    .iter_mut()
                    .find(|message| {
                        runtime_json_field_eq(message, "type", "assistant")
                            && message.get("content").and_then(Json::as_array).is_some_and(
                                |content| {
                                    content
                                        .iter()
                                        .any(|block| runtime_json_field_eq(block, "id", "t1"))
                                },
                            )
                    })
            {
                assistant["content"]
                    .as_array_mut()
                    .unwrap()
                    .push(duplicate.clone());
            }
        }
        for id in batches.iter().flat_map(|batch| &batch.ids) {
            let token = RuntimeString::from_utf8("$PARALLEL_TOOL_RESULT_UUID:").concat(id);
            let raw_uuid = RuntimeString::from_utf8("raw-result-").concat(id);
            for message in &mut trace.history {
                if runtime_json_field_eq(message, "type", "tool_result")
                    && message.get("toolUseId").and_then(Json::as_str) == Some(id)
                    && message.get("uuid").and_then(Json::as_str) == Some(&token)
                {
                    message["uuid"] = Json::String(raw_uuid.clone());
                }
            }
            for request in &mut trace.model_requests {
                for message in request["messages"].as_array_mut().unwrap() {
                    if runtime_json_field_eq(message, "type", "tool_result")
                        && message.get("toolUseId").and_then(Json::as_str) == Some(id)
                        && message.get("uuid").and_then(Json::as_str) == Some(&token)
                    {
                        message["uuid"] = Json::String(raw_uuid.clone());
                    }
                }
            }
        }

        let error = normalize_parallel_tool_result_uuids(
            &batches,
            &mut trace.history,
            &mut trace.model_requests,
        )
        .err()
        .expect("duplicate history tool_use must be rejected");
        assert!(
            error
                .to_string()
                .contains("exactly one visible history tool_use"),
            "{error}"
        );
    }

