    #[tokio::test]
    async fn live_recording_model_replays_declared_prelude_then_delegates_and_records() {
        struct DelegatingProvider {
            info: ProviderInfo,
            calls: Arc<AtomicUsize>,
        }

        impl ModelProvider for DelegatingProvider {
            fn info(&self) -> &ProviderInfo {
                &self.info
            }

            fn capabilities(&self, _model: &RuntimeString) -> ProviderCapabilities {
                ScriptedProvider {
                    info: self.info.clone(),
                }
                .capabilities(&rs("claude-live"))
            }

            fn stream(&self, _req: ModelRequest, _signal: AbortSignal) -> ModelStream {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Box::pin(futures::stream::iter(vec![
                    ModelStreamEvent::MessageStart {
                        model: rs("claude-live"),
                    },
                    ModelStreamEvent::TextDelta { text: rs("REAL") },
                ]))
            }
        }

        fn request(text: &str) -> ModelRequest {
            runtime_codec::decode_value(&exact_json!({
                "model":"claude-live",
                "system":[],
                "messages":[{
                    "type":"user",
                    "uuid":(RuntimeString::from(format!("user-{text}"))),
                    "content":[{"type":"text","text":(rs(text))}]
                }],
                "tools":[],
                "maxOutputTokens":128
            }))
            .unwrap()
        }

        let provider_calls = Arc::new(AtomicUsize::new(0));
        let provider: Arc<dyn ModelProvider> = Arc::new(DelegatingProvider {
            info: ProviderInfo {
                name: rs("anthropic"),
                base_url: None,
                env_key: None,
                default_model: rs("claude-live"),
            },
            calls: Arc::clone(&provider_calls),
        });
        let capture = LiveModelCapture::new(1);
        let prelude_stop = runtime_codec::decode_value::<ModelStreamEvent>(&exact_json!({
            "type":"message_stop",
            "stopReason":"end_turn",
            "usage":{"inputTokens":1,"outputTokens":1}
        }))
        .unwrap();
        let call_model = recording_live_call_model(
            provider,
            vec![vec![
                ModelStreamEvent::MessageStart {
                    model: rs("$MODEL"),
                },
                ModelStreamEvent::TextDelta {
                    text: rs("PRELUDE"),
                },
                prelude_stop.clone(),
            ]],
            "claude-live",
            capture.clone(),
        )
        .unwrap();

        let first = call_model(request("first"), AbortSignal::new())
            .collect::<Vec<_>>()
            .await;
        assert_eq!(
            first,
            vec![
                ModelStreamEvent::MessageStart {
                    model: rs("claude-live")
                },
                ModelStreamEvent::TextDelta {
                    text: rs("PRELUDE")
                },
                prelude_stop
            ]
        );
        assert_eq!(provider_calls.load(Ordering::SeqCst), 0);

        let second = call_model(request("second"), AbortSignal::new())
            .collect::<Vec<_>>()
            .await;
        assert_eq!(
            second,
            vec![
                ModelStreamEvent::MessageStart {
                    model: rs("claude-live")
                },
                ModelStreamEvent::TextDelta { text: rs("REAL") }
            ]
        );
        assert_eq!(provider_calls.load(Ordering::SeqCst), 1);
        let requests = capture.finish().unwrap();
        assert_eq!(requests.len(), 2);
        assert_eq!(requests[0].messages, request("first").messages);
        assert_eq!(requests[1].messages, request("second").messages);
    }

