    #[test]
    fn live_prelude_whole_fixture_hash_rejects_text_tool_and_stop_drift() {
        fn replace_once(source: &[u8], from: &[u8], to: &[u8]) -> Vec<u8> {
            let index = source
                .windows(from.len())
                .position(|window| window == from)
                .expect("mutation needle must exist");
            let mut mutated = source.to_vec();
            mutated.splice(index..index + from.len(), to.iter().copied());
            mutated
        }

        let original = LIVE_PRELUDE_BOUNDARIES_BYTES;
        for mutated in [
            replace_once(
                original,
                b"Calling the oversized-output fixture.",
                b"Calling a corrupted oversized fixture.",
            ),
            replace_once(
                original,
                b"\"name\":\"spill_probe\"",
                b"\"name\":\"spill_broke\"",
            ),
            replace_once(
                original,
                b"\"stopReason\":\"tool_use\"",
                b"\"stopReason\":\"end_turn\"",
            ),
        ] {
            let error = parse_live_prelude_boundaries(&mutated).unwrap_err();
            assert!(error.to_string().contains("whole-fixture hash mismatch"));
        }
    }

