    #[tokio::test]
    async fn live_prelude_must_be_fully_consumed_before_delegation() {
        struct CountingProvider {
            info: ProviderInfo,
            calls: Arc<AtomicUsize>,
        }

        impl ModelProvider for CountingProvider {
            fn info(&self) -> &ProviderInfo {
                &self.info
            }

            fn capabilities(&self, _model: &RuntimeString) -> ProviderCapabilities {
                ScriptedProvider {
                    info: self.info.clone(),
                }
                .capabilities(&rs("claude-live"))
            }

            fn stream(&self, _req: ModelRequest, _signal: AbortSignal) -> ModelStream {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Box::pin(futures::stream::empty())
            }
        }

        fn request(text: &str) -> ModelRequest {
            runtime_codec::decode_value(&exact_json!({
                "model":"claude-live",
                "system":[],
                "messages":[{
                    "type":"user",
                    "uuid":(RuntimeString::from(format!("user-{text}"))),
                    "content":[{"type":"text","text":(rs(text))}]
                }],
                "tools":[],
                "maxOutputTokens":128
            }))
            .unwrap()
        }

        let calls = Arc::new(AtomicUsize::new(0));
        let provider: Arc<dyn ModelProvider> = Arc::new(CountingProvider {
            info: ProviderInfo {
                name: rs("anthropic"),
                base_url: None,
                env_key: None,
                default_model: rs("claude-live"),
            },
            calls: Arc::clone(&calls),
        });
        let capture = LiveModelCapture::new(1);
        let call_model = recording_live_call_model(
            provider,
            vec![vec![
                ModelStreamEvent::MessageStart {
                    model: rs(LIVE_MODEL_TOKEN),
                },
                ModelStreamEvent::MessageStop {
                    stop_reason: crate::types::provider::ModelStopReason::EndTurn,
                    usage: runtime_codec::decode_value(&exact_json!({
                        "inputTokens":1,
                        "outputTokens":1
                    }))
                    .unwrap(),
                },
            ]],
            "claude-live",
            capture.clone(),
        )
        .unwrap();

        let unconsumed = call_model(request("prelude"), AbortSignal::new());
        drop(unconsumed);
        let _ = call_model(request("real"), AbortSignal::new())
            .collect::<Vec<_>>()
            .await;
        assert_eq!(calls.load(Ordering::SeqCst), 0);
        assert!(capture
            .finish()
            .unwrap_err()
            .to_string()
            .contains("before completion"));
    }

    #[test]
